INSERT INTO `anime_anime` VALUES
(1,94664,'무직전생 ~이세계에 갔으면 최선을 다한다~','애니메이션','\'나는 이 세계에서 최선을 다하겠어!\' 34세 총각에 무직인 방구석 폐인이었던 남자. 그는 부모님의 장례식 날에 집에서 쫓겨나 트럭에 치여 목숨을 잃었다. 다시 눈을 떴을 때 그는 검과 마법이 존재하는 이세계에서 아기로 다시 환생해 있었다! 쓰레기처럼 살아온 남자는 소년 루데우스로서 이세계에서 최선을 다해 살아가기로 맹세한다! 루데우스를 기다리는 것은 로리 마술사, 엘프 귀를 가진 소꿉친구, 흉포한 새침데기 아가씨와 그 외 다양한 인간들과의 만남. 그리고 가혹한 모험과 전투. 그의 새로운 인생이 움직이기 시작한다! \'인생 재시작\' 판타지, 개막!','https://image.tmdb.org/t/p/w500/bKGRbhv6ivalbt9sMniyxLVGnUZ.jpg',8.467,'https://image.tmdb.org/t/p/original/j9fRIimor0AMFJR9kjZubXcABzZ.jpg','2021-01-11','無職転生 ～異世界行ったら本気だす～'),
(2,65942,'Re: 제로부터 시작하는 이세계 생활','애니메이션','편의점에서 돌아가는 길. 갑자기 이세계로 날아간 소년, 나츠키 스바루.  무력한 소년이 손에 넣은 유일한 힘. 그것은 죽어서 시간을 되돌리는 사망귀환의 힘이었다.  소중한 사람을 지키기 위해. 그리고 분명히 존재했던 하나뿐인 시간을 되찾기 위해.  소년은 가혹한 운명에 맞선다.  널 구하기 위해서라면, 난 몇 번이든 죽겠어!','https://image.tmdb.org/t/p/w500/i7rka8OksNjM0BXjTmz8zwEDfO1.jpg',8.01,'https://image.tmdb.org/t/p/original/7ZruEnSnHD6Jx5mF0hBt1E306Vt.jpg','2016-04-04','Re:ゼロから始める異世界生活'),
(3,65733,'신 도라에몽','애니메이션','도라에몽과 진구 친구의 이야기','https://image.tmdb.org/t/p/w500/vhythNI2xgNwXLmDvZzw6f48uPg.jpg',8.082,'https://image.tmdb.org/t/p/original/c2oiRa7V3bQzof4wVGzLXtWJ5QU.jpg','2005-04-22','ドラえもん'),
(4,65336,'3월의 라이온','애니메이션','도쿄 시타마치에서 혼자 사는 17세의 프로 쇼기(일본 장기)기사 키리야마 레이. 하지만 그는 어린 시절 사고로 가족을 잃고, 깊은 고독을 안은 채 살아가는 소년이었다. 살아가기 위해 장기를 잡고, 그로 인해 다시 고뇌하는 그의 앞에 나타난 것은 아카리, 히나타, 모모 세 자매. 밝고 상냥한 그녀들과 접하는 동안 레이에게도 변화가 찾아오는데…….','https://image.tmdb.org/t/p/w500/4LTg5dLXnHwbNcFyOTnXvMpSs4q.jpg',8,'https://image.tmdb.org/t/p/original/mLzJpP9YRexGbvgiqunirAM5HAA.jpg','2016-10-08','３月のライオン'),
(5,57911,'도라에몽','애니메이션','도라에몽은, 무엇을 해도 안 되는 진구를 돕기 위해 22 세기의 세계로부터 왔다. 진구는 비실이나 퉁퉁이로부터 여느 때처럼 괴롭힘을 당하고, 엄마나 학교의 선생님에게도 언제나 혼난다. 더군다나 학교에서는 낮잠을 자기 때문에 시험는 언제나 0점이다. 도라에몽은, 그런 진구를 미래의 편리한 도구로 돕는다. 그러나 때로는 진구가 언제나 도라에몽의 도구에 의지하기 때문에, 그를 차갑게 대하여 진구를 자립 시키려고 한다. 그러나, 진구는 장래의 결혼상대인 이슬이에게 버림받지 않기 위해서 노력하지만, 계속 실패를 반복한다. 도라에몽은 이러한 진구, 이슬이, 비실이, 퉁퉁이를 둘러싼 일상 생활을 그린 작품','https://image.tmdb.org/t/p/w500/s4Z0qQHQame1xeZlwqiMOIkhqBn.jpg',7.7,'https://image.tmdb.org/t/p/original/6oVBODwFvbDJczBFlf4J930jKZg.jpg','1979-04-02','ドラえもん'),
(6,45845,'페이트 / 제로','애니메이션','기적을 일으키는 만능의「성배」를 손에 넣기 위해 7명의 마술사가 서번트라 불리우는 7명의 「영령」을 소환하여 최후이 1명이 남을 때까지 벌이는 살육전을 다룬 애니메이션','https://image.tmdb.org/t/p/w500/hfTEDISVpFMqmp6uOGylsSakyXZ.jpg',7.992,'https://image.tmdb.org/t/p/original/l6UO4qEHwUdjPyavbP6yGA06cS3.jpg','2011-10-02','Fate/Zero'),
(7,95479,'주술회전','애니메이션','소년은 싸운다 \'올바른 죽음\'을 위해  쓰라린 고통, 후회, 치욕. 인간으로부터 흘러나온 부정적인 감정이 저주로 변해 일상에 숨어든다. 저주는 세상에 만연한 재앙의 근원이며, 최악의 경우 인간을 죽음으로 이끈다. 그리고 저주는 저주로밖에 없앨 수 없다.  경이적인 신체능력을 가진 소년 이타도리 유지는 아주 평범한 고등학생이었지만, 어느 날 \'저주\'에 습격당한 친구를 구하기 위해 특급 주물 \'양면 스쿠나의 손가락\'을 먹고 영혼에 저주가 깃들게 된다. 저주인 \'양면 스쿠나\'와 몸을 공유하게 된 이타도리는 최강의 주술사인 고죠 사토루의 안내로 저주에 대항하는 전문 기관인 \'도쿄 도립 주술 고등전문학교\'에 편입하게 되는데... 저주를 없애기 위해 저주가 된 소년의 돌이킬 수 없는 장렬한 이야기가 움직이기 시작한다.','https://image.tmdb.org/t/p/w500/pnn223i9v5kfYku6TbqdSbPePJp.jpg',8.583,'https://image.tmdb.org/t/p/original/lthkKBLe1rX6iThgVFg22O02sJw.jpg','2020-10-03','呪術廻戦'),
(8,30984,'블리치','애니메이션','\'쿠로사키 이치고\'는 유령을 볼 수 있는 15세의 남자다. 특수한 체질을 가지고도 평범한 생활을 하던 이치고에게 갑자기 스스로를 사신이라고 소개하는 소녀 \'쿠치키 루키아\'가 나타난다. 유아울러 산 사람, 죽은 사람 안 가리고 공격해서 영혼을 먹어치우는 나쁜 혼령 \'호로\'도 모습을 드러낸다. 그런데 호로로 인해 이치고의 가족이 쓰러져가는데...','https://image.tmdb.org/t/p/w500/2cT8jkEVsAL86CVKALR4pnaVLDb.jpg',8.366,'https://image.tmdb.org/t/p/original/o0NsbcIvsllg6CJX0FBFY8wWbsn.jpg','2004-10-05','BLEACH'),
(9,60572,'포켓몬스터','애니메이션','관동지방의 태초마을에 살고 있는 주인공 지우는 오박사로부터 피카츄와 몬스터볼, 포켓몬도감을 받아 포켓몬 마스터를 목표로 여행을 나선다. 회색체육관, 갈색체육관 등에서 격렬한 시합과 여러 곳에서 이루어지는 포켓몬과의 만남.','https://image.tmdb.org/t/p/w500/vaXQOBNdQVtxUMN96cR4qQRxmoQ.jpg',7.99,'https://image.tmdb.org/t/p/original/60TX5aaN7DHZNOEbRdTkag2J5qs.jpg','1997-04-01','ポケットモンスター'),
(10,30983,'명탐정 코난','애니메이션','검은 조직의 약물에 당해서 초등학생의 몸이 된 고등학생 쿠도 신이치가 에도가와 코난이라는 가명을 사용하여 소꿉친구인 란의 아버지가 운영하는 탐정사무소에서 얹혀 살며 사건을 해결하는 이야기를 다루고 있다.','https://image.tmdb.org/t/p/w500/tg5Gya0yv7mScUMIX8CSXZzLCVd.jpg',8.017,'https://image.tmdb.org/t/p/original/z67lpMtm8YGykJO4p89meuNMvj8.jpg','1996-01-08','名探偵コナン'),
(11,46298,'헌터x헌터','애니메이션','곤프릭스는 보물섬에 사는 어린 소년이다. 곤은 아버지가 죽었다고 알려준 ‘헌터’ 카이트로부터 가르침을 받았지만, 아버지가 어디에선가 생존하여 최고의 헌터로 목숨을 걸고 미지의 아이템, 숨겨진 보물이나 진본을 찾아 다니고 있다고 생각한다. 곤은 전문 헌터가 되기로 결심하고 섬을 떠난다. 헌터가 되기 위해서는 반드시 헌터시험을 통과해야 되는데, 그 와중에 다른 세 명의 지원자 크라피카, 레오리오, 키르아와 친구가 된다. 곤은 이 어려운 관문을 넘어서 세계 최고의 헌터가 될 수 있을까? 그리고 아버지를 만날 수 있을까?','https://image.tmdb.org/t/p/w500/8YKlXBit3PlVTXf9A1ohccCf9lQ.jpg',8.7,'https://image.tmdb.org/t/p/original/bFKKyCI89Xq98Gul8cGox8K3sZa.jpg','2011-10-02','HUNTER×HUNTER'),
(12,30623,'짱구는 못말려','애니메이션','5살 유치원생 짱구, 발 냄새가 심한 아빠, 바겐세일을 무척 좋아하는 엄마, 보석과 미남을 좋아하는 짱아, 평범한 듯 소란스러운 짱구 가족의 이야기.','https://image.tmdb.org/t/p/w500/1mQZZjZdFXXSUyGpEuPb3PThiE6.jpg',7.7,'https://image.tmdb.org/t/p/original/70xTjXpb0kfOhTRJqKwDYSG8Kle.jpg','1992-04-13','クレヨンしんちゃん'),
(13,209867,'장송의 프리렌','애니메이션','용사 힘멜 일행과 함께 10년에 걸친 모험 끝에 마왕을 물리치고 세계에 평화를 가져온 마법사 프리렌. 천 년을 넘게 사는 엘프인 그녀는 힘멜 일행과 재회를 약속하고 혼자 여행을 떠난다. 그로부터 50년 후 프리렌은 힘멜을 찾아갔지만 50년 전과 달라진 게 없는 그녀에 비해 힘멜은 늙었고 수명이 얼마 남아있지 않았다. 그 후 죽음을 맞이한 힘멜을 보고 지금까지 \'인간을 아는\' 일을 하지 않았던 것을 후회하고 자신을 반성한 프리렌은 \'인간을 알기 위한\' 여행을 떠난다. 그 여로에는 다양한 사람들과의 만남, 다양한 사건들이 기다리고 있었는데──.','https://image.tmdb.org/t/p/w500/mnj30hYDVAbL9BOA0f4HrKubAGF.jpg',8.806,'https://image.tmdb.org/t/p/original/rBOnrVlck7BIlGeWVlzYiZeg4l2.jpg','2023-09-29','葬送のフリーレン'),
(14,259140,'란마1/2','애니메이션','텐도 아카네 앞에 초면인 약혼남 사오토메 란마가 나타난다. 게다가 천재 무술 소년 란마에겐 대반전의 비밀이 있는데. 바로, 찬물을 뒤집어쓰면 소녀로 변신하는 것.','https://image.tmdb.org/t/p/w500/yOFvSq8YGKSVvnbCc6IY4PWEssa.jpg',8.148,'https://image.tmdb.org/t/p/original/xvD9urN8lUtWw5fm4a87Rl3dCZn.jpg','2024-10-06','らんま1/2'),
(15,220150,'포켓몬스터','애니메이션','라이징 볼트태클즈에 가입한 신예 포켓몬 트레이너 리코와 로드. 베일에 싸인 조직, 익스플로러즈의 음모를 막으며 포켓몬의 세계에서 종횡무진 모험을 펼친다.','https://image.tmdb.org/t/p/w500/bHBf7URUEZGUPORE6dp1hDtSUt9.jpg',8.7,'https://image.tmdb.org/t/p/original/d0axpGojOqDag5lDa0eNSEtw11l.jpg','2023-04-14','ポケットモンスター'),
(16,120089,'스파이 패밀리','애니메이션','사람은 누구나 아무에게도 보여줄 수 없는 자신을 갖고 있다. 세계 각국이 물밑에서 치열하게 정보전을 펼치는 시대. 오스타니아와 웨스탈리스는 십수 년간에 걸쳐 냉전 상태에 있었다. 웨스탈리스의 정보국 대동과 \'WISE\' 소속의 수완가 스파이인 \'황혼\' 은 동서 평화를 위협하는 위험인물, 오스타니아의 국가통일당 총재 도노반 데스몬드의 동향을 살피기 위해 어떤 극비 임무를 수행하게 된다. 그 이름은 오퍼레이션 \'올빼미\'. 임무 내용은 \"일주일 이내에 가족을 만들어, 데스몬드의 아들이 다니는 명문 학교의 친목회에 잠입하라\". \'황혼\' 은 정신과 의사 로이드 포저로 위장하고 가족을 만들게 된다. 하지만, 그가 만난 딸 아냐는 마음을 읽을 수 있는 초능력자, 아내 요르는 암살자였다! 3명의 이해가 일치하여 서로 정체를 숨기면서 함께 생활하게 되는데. 해프닝 연속인 임시 가족에게, 세계의 평화는 맡겨졌다.','https://image.tmdb.org/t/p/w500/rikBBQHmCTOiZ7YoJVkYcKdXgNx.jpg',8.506,'https://image.tmdb.org/t/p/original/lysUnU6V0VfcthDbviuVlIqgHOR.jpg','2022-04-09','SPY×FAMILY'),
(17,12971,'드래곤볼 Z','애니메이션','흥미진진한 드래곤 볼! 계속되는 이야기! 성장한 손오공이 치치와 결혼하여 손오반이라는 아들까지 둔 모습을 보여주고 있다. 어느 날 우주로부터 형 라데츠가 찾아와 지구를 멸망시키려고 하며 손오공에게 동참할 것을 설득한다. 하지만, 자신의 설득이 먹혀들지 않자 조카인 오반을 납치한다. 오공과 피콜로가 합심하여 라데츠를 물리치지만, 오공도 죽어버리는 사태가 발생한다. 지구를 위해, 그리고 우주를 위해 싸우는 Z 용사들!','https://image.tmdb.org/t/p/w500/70gAmYUfEVOFMuC3gJBIo0MSfbh.jpg',8.374,'https://image.tmdb.org/t/p/original/ydf1CeiBLfdxiyNTpskM0802TKl.jpg','1989-04-26','ドラゴンボールゼット'),
(18,46260,'나루토','애니메이션','<주간 소년 점프>에 연재되면서 폭발적인 인기를 모았던 \'나루토\'를 애니메이션으로 만들었다. 한국에서도 단행본이 나와 많은 인기를 얻고 있다. 나루토와 동료들이 닌자가 되기 위한 모험을 떠나는 흥미진진한 작품. \n\n닌자 마을 중 하나인 나뭇잎 마을. 매일같이 장난만 치며 공부도 뒤쳐져서 졸업조차 불안하기만 한 문제아 나루토. 그런 그이지만 마을에서 제일 가는 닌자, \'호카게\'가 되고 싶다는 커다란 꿈을 지니고 있다. 하지만, 자신의 출생의 비밀을 안 나루토는 결의를 새롭게 다지고 같은 학교 학생인 사스케, 사쿠라와 함께 닌자로서의 첫 발을 내딛게 된다.','https://image.tmdb.org/t/p/w500/5llYnYzA2oiTxxSi9d7RSanrwR8.jpg',8.363,'https://image.tmdb.org/t/p/original/5F0HVEgkgP99fEWDjPyikGt9jQi.jpg','2002-10-03','ナルト'),
(19,97617,'마왕학원의 부적합자 ~사상 최강의 마왕인 시조, 전생해서 자손들의 학교에 다니다~','애니메이션','2천 년의 시간을 넘어 되살아난 포학의 마왕\n\n하지만, 마왕 후보를 육성하는 학원의 적성 \'부적합\'?!\n\n인간도, 정령도, 신들마저도 죽였지만 계속되는 투쟁에 질려  평화로운 세상을 꿈꾸며 전생한 포학의 마왕 \'아노스 볼디고드\'\n\n하지만 2천 년 후 전생한 그를 기다리고 있던 것은\n\n평화에 길들여져서 너무 나약해진 자손들과 급격하게 쇠퇴한 마법이었다.\n\n마왕의 환생이라고 생각되는 자를 모아서 교육하는\n\n\'마왕학원\'에 입학한 아노스였지만\n\n학원은 그의 힘을 알아보지 못하고 부적합자의 낙인을 찍어 버린다.\n\n게다가 전설의 마왕은 자신과는 전혀 다른 사람이 되어 있었다.\n\n주위로부터 경멸의 시선을 받던 중에도  항상 가까이에 있어 준 소녀 미샤를 수하로 거두고\n\n부적합자(마왕)이 마족의 계급 피라미드를 뛰어 올라간다!!\n\n\'섭리든 운명이든 기적이든 내 앞에서는 그저 부복하고 사라질 뿐이다\'...','https://image.tmdb.org/t/p/w500/b5FbuBwBaWzMIDpqpHCQCL8PrQf.jpg',8.402,'https://image.tmdb.org/t/p/original/fxISKAY8c2xYXt2CFLjUU2bEx8n.jpg','2020-07-04','魔王学院の不適合者 ～史上最強の魔王の始祖、転生して子孫たちの学校へ通う～'),
(20,45790,'죠죠의 기묘한 모험','애니메이션','유서 깊은 죠스타 가문에 얽힌 기묘한 이야기를 아는가. 각기 다른 세상에서 애칭 \'죠죠\'를 공유하며 살아가는 주인공들. 시간적 공간적 배경은 달라도, 추구하는 가치는 다르지 않다. 악의 세력을 물리치고 정의가 이기는 세상을 만들라.','https://image.tmdb.org/t/p/w500/9kav2ODiGILqV86XWSUn6g4KQq5.jpg',8.561,'https://image.tmdb.org/t/p/original/mLKN1dsimKPiXCZ48KED0X8a02t.jpg','2012-10-06','ジョジョの奇妙な冒険'),
(21,42912,'썬더 일레븐','애니메이션','천둥 중학교 축구부의 주장 강수호는 고민에 빠져 있었다. 팀은 멤버가 부족해 해체 직전의 위기에 놓여 있었고, 이대로라면 공식 경기에 출전할 수도 없는 상황이었다. 그러던 어느 날, 천둥 중학교에 한 학생이 전학을 오게 된다. 바로 전설적인 스트라이커, 염성화였다. 강수호는 염성화를 팀으로 영입할 계획을 세운다.\n\n이 두 사람의 만남이 약소 축구부의 운명을 바꾸게 된다!','https://image.tmdb.org/t/p/w500/qZFMDCZtMWgj9zhKo3tVJpfE81g.jpg',8,'https://image.tmdb.org/t/p/original/zhtEYosjlYtNavbvImxcs36We4i.jpg','2008-10-05','イナズマイレブン'),
(22,57706,'란마 ½','애니메이션','찬물을 뿌리면 여자로 더운물을 뿌리면 원래의 남자로 돌아간다는 특이한 설정과 타카하시 루미꼬 특유의 개그로 높은 인기를 누렸던 원작 만화를 TV시리즈 화한 것으로 원작의 분위기나 개그를 잘 살려낸 애니메이션으로 평가받고 있다. 텐도 도장에 중국으로 수련하러 아버지의 친구와 그 아들이 도착한다는 소식에 집안이 어수선해진다. 아카네의 아버지는 친구의 아들과 자신의 딸을 결혼시켜 도장을 잇게 할 기대에 부풀어 있으나 도착한 것은 귀여운 여자아이와 한 마리 거대한 판다. 란마의 정체를 알게 된 아카네의 아버지는 카스미, 나비키, 아카네 중에서 란마의 약혼자를 결정하도록 하고 하지만 카스미와 나비키는 관심도 보이지 않은 채 아카네에게 약혼 건을 떠밀어 버리고 란마는 텐도 도장에 머물게 된다.','https://image.tmdb.org/t/p/w500/6LmWAQFMD2j8gTUGgmD8vq7xxyA.jpg',8.621,'https://image.tmdb.org/t/p/original/dI2O0d5Dkk8tpuTvCkUKQw3LNMv.jpg','1989-04-15','らんま1/2'),
(23,3570,'달의 요정 세일러문','애니메이션','지구의 평화를 지키기 위해 적과 싸우는 소녀들의 이야기를 그린 애니메이션','https://image.tmdb.org/t/p/w500/oCgEdfayxG8GoPydrlF2ZjcJyCL.jpg',8.4,'https://image.tmdb.org/t/p/original/sNCpbcCcRadDBMTh6An1dBMakqr.jpg','1992-03-07','美少女戦士セーラームーン'),
(24,127532,'나 혼자만 레벨업','애니메이션','다른 차원과 이쪽 세계를 이어주는 통로인 \'게이트\'가 갑자기 발생한 뒤 10년 세계에는 \'헌터\'라고 불리는 초인적인 힘에 각성한 사람들이 출현했다. 헌터는 게이트 안의 던전을 공략하고 대가를 받는 것을 생업으로 하고 있는데 그런 강자들만 가득한 헌터들 중 \'성진우\'는 인류 최약병기라고 불리는 저랭크 헌터로서 생활하고 있었다. 어느 날, 저랭크 던전에 숨겨진 고랭크 이중 던전을 발견했지만 빈사의 중상을 입은 성진우의 눈앞에 의문의 퀘스트창이 나타났는데. 죽음의 순간, 퀘스트를 수락하기로 결심한 성진우는 자신만 \'레벨업\'할 수 있게 되었는데.','https://image.tmdb.org/t/p/w500/5gR5oCQufzZ6tPcFoHb61ckiwiP.jpg',8.7,'https://image.tmdb.org/t/p/original/xMNH87maNLt9n2bMDYeI6db5VFm.jpg','2024-01-07','俺だけレベルアップな件'),
(25,37854,'원피스','애니메이션','해적왕을 꿈꾸는 소년 루피와 동료들의 유쾌한 모험담을 그린 작품! 힘있는 연출과 개성있는 그림체 및 캐릭터들의 활기찬 묘사로 인기를 모았으며, 1억 만부 이상 판매된 원작만화의 인기를 바탕으로 다양한 버전으로 제작된 초히트작 애니메이션이다.\n\n˝최고의 해적왕˝을 꿈꾸는 루피와 동료들의 파란만장한 모험담 !\n\n떄는 해적들이 난무하는 ‘춘추전국시대’. 곳곳에서는 전설적인 해적왕 골드로저가 남긴 보물 ‘원피스’를 놓고 수많은 해적들이 서로 싸우고 있었다. 어릴 때부터 골드로저를 너무도 동경한 나머지 자신도 전설의 해적왕이 되는 것이 꿈인 주인공 루피. 그러나 루피는 악마의 열매를 먹은 이후로 몸을 자유자재로 늘일 수 있지만 수영을 할 수가 없는 처지이다. 바다가 주 활동무대인 해적에게 있어 수영은 필수. 그러나 해적왕을 꿈꾸는 루피는 수영을 할 수 없음에도 불구하고 물에 빠지지 않으면 된다면서 자신의 꿈을 향해 모험을 떠난다. 그 과정에서 만나게 되는 현상금 헌터 ‘조로’, 자칭 해적전문 도둑인 ‘나미’, 저격수 ‘우솝, 그리고 주방장 ‘상디’까지. 지금부터 루피와 그의 동료 4명이 함께하는 해적의 꿈을 향한 파란만장한 모험이 펼쳐진다','https://image.tmdb.org/t/p/w500/qHjXsSUuolEtbgvYPzRjAuB1VHE.jpg',8.748,'https://image.tmdb.org/t/p/original/2rmK7mnchw9Xr3XdiTFSxTTLXqv.jpg','1999-10-20','ワンピース'),
(26,45857,'가정교사 히트맨 리본!','애니메이션','후회하라! 필살탄이 당신을 REBORN(부활)시킬 것이다!! 바보 같은 인생을 보내는 중학생 츠나의 집에 가정교사가 오게 되었다. 가정교사의 이름은 리본! 보기에는 어린아이지만, 실제 본업은 초일류 히트맨…?! 리본은 사실 본고라 조직의 10대 보스를 키우기 위해 이탈리아에서 건너온 살인 청부업자였다! 차기 보스로서 그의 타깃이 된 사람은 학교에서 제대로 하는 일이 없어 항상 왕따를 당하는 츠나라는 소년! 죽을힘을 다하면 뭐든지 가능하다?! 츠나의 목숨을 건 수업이 시작됐다!!','https://image.tmdb.org/t/p/w500/7uzY5uXrTkd4gxwKoIbvE1fMHHG.jpg',8.181,'https://image.tmdb.org/t/p/original/3wztM15Bq7TX3Kc8IzApqsOQQjK.jpg','2006-10-07','家庭教師ヒットマン REBORN!'),
(27,93653,'허구추리','애니메이션','요괴들의 지혜의 신이 되어, 날마다 요괴들로부터 오는 트러블을 해결하고 있는 소녀와 그녀가 첫눈에 반한 요괴조차 두려워하는 남자가 함께 요괴들이 일으키는 미스터리한 사건에 맞서는 연애 X 전기 X 미스터리 애니메이션','https://image.tmdb.org/t/p/w500/t1yzT9M6TbDXD5EVaQg4xc3il7m.jpg',7.73,'https://image.tmdb.org/t/p/original/ujypWFhRcrb4KXjsp1edGomN2RI.jpg','2020-01-12','虚構推理'),
(28,69500,'나츠메 우인장','애니메이션','어릴 적부터 인간이 아닌 것들, 다시 말해 \'요괴\'를 보아온 소년 나츠메 타카시. 부모님이 사고로 돌아가신 후 친척집을 전전하며 살아온 나츠메는 그 특이한 체질 때문에 주위의 사람들로부터 경원시당해 왔다. 고등학생이 된 나츠메는 한적한 시골 마을에 위치한 후지와라 부부의 집에 맡겨지고, 자신을 친자식처럼 따뜻하게 맞이해 준 이 부부에게만큼은 요괴를 볼 수 있다는 자신의 비밀을 들키지 않겠다고 맹세한다. 그러나 문제는 나츠메에게 남겨진 외할머니 레이코의 유품인 \'우인장\'이었다. 나츠메와 마찬가지로 요괴를 볼 수 있으며 또한 상당한 힘을 지니고 있었던 레이코는 살아 생전에 요괴들과 싸움을 벌여 자신에게 진 요괴들의 이름을 수첩에 봉인하여 \'우인장\'을 만들었다. 요괴의 이름을 지배하면 요괴를 지배할 수 있다고 하며, 다시 말해 우인장에 이름이 적혀 있다는 것은 우인장의 주인에게 생사여탈권을 저당잡혀 있다는 사실이 된다. 우인장이 나츠메의손으로 넘어왔다는 사실을 알게 된 요괴들은 자신의 이름을 돌려받기 위해 우인장을 노리게 되지만. 가능한 한 요괴들에게 이름을 돌려주고자 하는 나츠메는 자칭 수호자인 복고양이 형상의 요괴 야옹선생과 함께 요괴들과의 교류를 시작하는데...','https://image.tmdb.org/t/p/w500/4CBkTixgJnsriTLjsaO1wEQeqwF.jpg',8.156,'https://image.tmdb.org/t/p/original/xHjRfQIRlxug491JrKiEYl9vHM1.jpg','2008-07-08','夏目友人帳'),
(29,220542,'약사의 혼잣말','애니메이션','독과 약에 관한 지식에 심취한 황궁의 하녀. 유곽에서 약사 노릇을 했던 경험을 살려 의문의 사건들을 하나씩 해결해 나간다.','https://image.tmdb.org/t/p/w500/vy9rMVergbppBCflHJyT78dz7mz.jpg',8.628,'https://image.tmdb.org/t/p/original/gffVOVZ2Y9cmVIZ26Gt9ByMGCYH.jpg','2023-10-22','薬屋のひとりごと'),
(30,236338,'마법소녀를 동경해서','애니메이션','나, 히이라기 우테나는 마법소녀를 정말 좋아하는 아주 평범한 여자아이 어느 날, 변신 능력을 주는 마스코트 같은 녀석을 만나 신기한 마법에 걸려버렸어! 이걸로 나도 마법소녀로──라고 생각했는데 어라? 뭐야 이 의상은? 악의 조직의 여간부라니 그게 무슨 소리야!? 앞으로 난 어떻게 되는 거야~~~!!? 마법소녀를 좋아하는 마음씨 착하고 내성적인 소녀가 사디스틱하게 대 변신!!? 정의와 악의 격렬한 SM 플레이(!?) 시작입니다!!','https://image.tmdb.org/t/p/w500/jUVtkDgulXh2IrfsGbcRgmuSz1Y.jpg',8.246,'https://image.tmdb.org/t/p/original/dvIguIZqqQKCt7YiKq7evfk5NW3.jpg','2024-01-03','魔法少女にあこがれて'),
(31,31910,'나루토 질풍전','애니메이션','<주간 소년 점프>에 연재되면서 폭발적인 인기를 모았던 \'나루토\'를 애니메이션으로 만들었다. 한국에서도 단행본이 나와 많은 인기를 얻고 있다. 나루토와 동료들이 닌자가 되기 위한 모험을 떠나는 흥미진진한 작품.  닌자 마을 중 하나인 나뭇잎 마을. 매일같이 장난만 치며 공부도 뒤쳐져서 졸업조차 불안하기만 한 문제아 나루토. 그런 그이지만 마을에서 제일 가는 닌자, \'호카게\'가 되고 싶다는 커다란 꿈을 지니고 있다. 하지만, 자신의 출생의 비밀을 안 나루토는 결의를 새롭게 다지고 같은 학교 학생인 사스케, 사쿠라와 함께 닌자로서의 첫 발을 내딛게 된다.','https://image.tmdb.org/t/p/w500/nZ2qXHJTtNAfa6cP1iw9onhA2H7.jpg',8.532,'https://image.tmdb.org/t/p/original/z0YhJvomqedHF85bplUJEotkN5l.jpg','2007-02-15','ナルト 疾風伝'),
(32,31572,'루팡 3세','애니메이션','진귀한 보물을 손에 넣기 위해 신출귀몰한 도둑 \'루팡\'과 친구들이 벌이는 좌충우돌 활약상을 그린 액션 애니메이션','https://image.tmdb.org/t/p/w500/A7uyuRYVSzkmuL0kG7ms7mIwM96.jpg',8.008,'https://image.tmdb.org/t/p/original/961SQWKlq6EQKN5lvXLR04YxSkw.jpg','1971-10-24','ルパン三世'),
(33,13916,'데스노트','애니메이션','야가미 라이토는 장래가 유망한 모범생이지만 마음속으로는 따분해하고 있었다. 그러던 어느날 \"데스노트\"를 발견한다. 데쓰노트는 사신의 세계에서 온 공책으로 원하는 방식으로 사람을 죽일 수 있는 힘이 있다. 데스노트를 손에 넣은 라이토는 범죄와 범죄자가 없는 그만의 완전한 세상을 만들기로 결심한다. 범죄자들이 하나씩 죽어가자 당국에서는 전설적 탐정인 L을 보내 범인을 추적한다. 그리하여 재치와 속임수와 논리의 대결이 펼쳐지는데...','https://image.tmdb.org/t/p/w500/chnG4pYo89weaBjXHJWvW68E35B.jpg',8.623,'https://image.tmdb.org/t/p/original/koBa94NxTaGe2FoDzlXMuJptsv0.jpg','2006-10-04','DEATH NOTE'),
(34,82684,'전생했더니 슬라임이었던 건에 대하여','애니메이션','어느 날 갑자기 나타난 괴한에게 습격당해 목숨을 잃은 미카미 사토루는 천문학적 확률로 이세계에 전생한다.\n\n그러나 왜인지 전생한 모습은, 최약체 몬스터로 유명한 슬라임이었다!\n\n이런 건 인정 못 해?! 라고 말하면서도 낯선 동굴에서 즐거운 슬라임 라이프를 만끽하지만...\n\n천재급 드래곤 『폭풍룡 베루도라』와 만남으로써, 운명의 수레바퀴는 움직이기 시작했다.\n\n몬스터 전생 판타지, 시작!','https://image.tmdb.org/t/p/w500/eeemfj0Zv0SQlAqpitn7caJQvWI.jpg',8.429,'https://image.tmdb.org/t/p/original/eJOy7YWAHgOS3V477sdTsq4v9jp.jpg','2018-10-02','転生したらスライムだった件'),
(35,35610,'이누야샤','애니메이션','사혼의 구슬을 노리던 이누야사는 금강의 화살에 맞아 봉인되고 사혼의 구슬은 금강의 죽음과 함께 영원히 사라지게 된다. 이야기는 현대로 돌아가 오래된 신사에 사는 중학교 3학년 가영은 어느 날 우연히 사당 안에 있는 우물 속에서 나타난 지네요괴를 만나게 되고 자신도 모르는 사이에 전국시대로 넘어오게 된다. 숲에서 봉인된 이누야샤와 만난 가영은 또 다시 지네 요괴의 습격을 받게 되고 이 요괴의 퇴치를 위해 이누야사의 봉인을 풀게 되는데...','https://image.tmdb.org/t/p/w500/8CXRXQWQT6jWEXlpElq1Eyuxza0.jpg',8.575,'https://image.tmdb.org/t/p/original/mVE1ULmLaYhCkBQPt3JC5xZC6T6.jpg','2000-10-16','犬夜叉'),
(36,30981,'몬스터','애니메이션','독일 아이슬러 기념병원에서 근무하는 일본인 의사 텐마 켄조는 빈사 상태의 소년 \'요한\'의 목숨을 살린다. 그 후 텐마는 연속살인범으로 경찰에 쫓기게 된다. 하지만 그 범인은 텐마가 9년 전 목숨을 구해준 요한이었다. 요한을 쫓는 텐마의 도피극이 시작된다.','https://image.tmdb.org/t/p/w500/7ZhHyA0IIQOyz1hzCXpTilXg4Q2.jpg',8.519,'https://image.tmdb.org/t/p/original/6T19aRp9zLMghZo1dTEwoNyreNZ.jpg','2004-04-07','MONSTER'),
(37,31911,'강철의 연금술사 BROTHERHOOD','애니메이션','죽은 어머니를 살리기 위해 시도한 금단의 연금술로 인해 신체의 일부와 전부를 빼앗긴 에드워드와 알폰스 형제. 동생 알폰스의 신체를 되찾기 위해 현자의 돌을 찾아나선다. 강철의 연금술사 오리지널판 이후 제작되어 원작 만화를 더욱 충실히 반영한 리메이크 버전이다.','https://image.tmdb.org/t/p/w500/9SkrxQDka8JAk8tUwb396prUR9J.jpg',8.714,'https://image.tmdb.org/t/p/original/2UG177tWHy7xRmMKWJHB7nAUmKd.jpg','2009-04-05','鋼の錬金術師 FULLMETAL ALCHEMIST'),
(38,65844,'이 멋진 세계에 축복을!','애니메이션','게임을 사랑하는 은둔형 외톨이 소년, 사토 카즈마의 인생은 너무나도 허무하게 그 막을 내린…… 줄 알았는데, 정신을 차려보니 눈앞에 여신을 자처하는 미소녀가 있었다.\n\n“이세계에 가지 않을래? 원하는 걸 딱 하나만 가지고 가게 해줄게.”\n\n“그럼 널 가지고 가겠어.”\n\n이리하여, 이세계로 넘어간 카즈마의 대모험이 시작…! 되나 싶었는데, 결국 시작된 것은 의식주 확보를 위한 노동이었다!\n\n카즈마는 그저 평온하게 살고 싶지만, 문제를 연달아 일으키는 여신 때문에 결국 마왕군에게 찍히고 마는데?!','https://image.tmdb.org/t/p/w500/kBSbQD4JtsqCiGPMRDsM76g4boP.jpg',8.549,'https://image.tmdb.org/t/p/original/rvZJxD36tKoglL8fXoMMWKGQfM.jpg','2016-01-14','この素晴らしい世界に祝福を！'),
(39,37567,'닥터 슬럼프','애니메이션','펭귄 마을의 천재 박사 \'슬럼프\'가 갑작스러운 번개 사고로 예상치 못했던 꼬마 로봇 \'아리\'를 탄생시키게 되며 벌어지는 애니메이션','https://image.tmdb.org/t/p/w500/AdTMMNiT8HGGlq17AwDTihsGzhF.jpg',7.929,'https://image.tmdb.org/t/p/original/4K9mqtNbipQI7qfmLN4xCNitLL4.jpg','1981-04-08','Dr.スランプ アラレちゃん'),
(40,67667,'베이블레이드 버스트','애니메이션','베틀 팽이 세계의 정점을 목표로 한 주인공의 성장 이야기를 그린 애니메이션','https://image.tmdb.org/t/p/w500/fG7BHxDlntPyB57UuNo9sXmAmLV.jpg',8.235,'https://image.tmdb.org/t/p/original/w7PYFLVjf19azUbkJmFxid0sIt3.jpg','2016-04-04','ベイブレードバースト'),
(41,46195,'바케모노가타리','애니메이션','흡혈귀와 만남. 그것은 나오에츠 고교 3학년 아라라기 코요미의 인생을 크게 뒤바꾸어 놓았다. 악몽과도 같았던 봄방학, 그리고 골든위크의 예기치 못했던 사건. 그리고 그런 그에게 또다시 새로운 괴이와 소녀들과의 인연이 시작된다. 게, 달팽이, 원숭이, 뱀, 고양이 아라라기 코요미와 괴이에 씌인 다섯 명의 소녀들의 이야기.','https://image.tmdb.org/t/p/w500/8Gp6GNDKBjC4p4I49GsacK83VrM.jpg',8.1,'https://image.tmdb.org/t/p/original/cHII6sQ91q8H5EMONKCwCQMauCP.jpg','2009-07-03','化物語'),
(42,64163,'새여동생 마왕의 계약자','애니메이션','바사리는 아버지의 갑작스러운 재혼 선언과 함께 미래 의붓 여동생이 될 두 소녀를 만난다. 아버지가 사라지자 돌변해버리는 태도에 당황스러워하는 것도 잠시, 이들 정체는 마왕 후보자와 서큐버스라는 걸 깨닫는다.','https://image.tmdb.org/t/p/w500/yFJl1I19BDcKdRhnphAWSUHXFqG.jpg',7.931,'https://image.tmdb.org/t/p/original/dXGaX995fsbiqJgFRj0CEJKxZVV.jpg','2015-01-07','新妹魔王の契約者'),
(43,42705,'더 파이팅','애니메이션','어려서 아버지를 여의고 어머니와 단 둘이 낚시 가게를 꾸려나가던 왕따 고교생 마쿠노우치 잇포는 같은 학교의 불량학생 우메자와 일행에게 괴롭힘을 당하던 중 로드워크 중인 카모가와 짐 소속의 간판 복서 타카무라 마모루의 도움을 받게되고 복싱을 동경, 강해지기 위해 복싱을 시작한다. 같은 나이의 복서 미야타 이치로와 선의의 라이벌이 되어 프로 복서가 되고, 경기를 치루면서 점점 진정한 강함이 무엇인지를 깨닫기 시작하는데...','https://image.tmdb.org/t/p/w500/a5g4AltmlNq0e1hN1jugemNa5wX.jpg',8.658,'https://image.tmdb.org/t/p/original/uvCkSZwCTKnBtBOvDpcOvQA6xBg.jpg','2000-10-03','はじめの一歩'),
(44,65931,'문호 스트레이독스','애니메이션','고아원에서 쫓겨나 굶어 죽기 일보 직전,\n\n아쓰시가 만난 너무나도 특이한 남자들.백주대낮에 물에 뛰어들어 자살을 시도하는\n\n자살 마니아 다자이 오사무.신경을 곤두세워 수첩을 기록하는\n\n안경남 구니키다 돗포.군인도 경찰도 손대지 못하는\n\n험난한 사건을 해결한다는 그들.운명의 장난인지, 아쓰시는\n\n\'식인 호랑이\' 퇴치를 요구받는데...항구 도시 요코하마.\n\n문호의 이름을 한 그들과\n\n기이한 힘이 만나, 이야기가 시작된다!','https://image.tmdb.org/t/p/w500/yY7eds57HBPNuD2SoPyHh9AmRcQ.jpg',8.253,'https://image.tmdb.org/t/p/original/79lc4Rocfnn9RIv1YlHC0jeBsqf.jpg','2016-04-07','文豪ストレイドッグス'),
(45,123249,'그 비스크 돌은 사랑을 한다','애니메이션','히나 인형의 얼굴을 만드는 \'카시라시\'를 꿈꾸는 남자 고교생 \'고죠 와카나\'. 성실하고 한결 같이 히나 인형 제작에 몰두하지만 같은 세대의 유행과는 동 떨어져  좀처럼 반 친구들과 친해지지 못했다. 그런 와카나에게 있어서 언제나 반의 중심에 있고 인기가 많은 \'키타가와 마린\'은 마치 다른 세계의 주민처럼 느껴졌다. 하지만 어느 날 생각지 못한 일을 계기로 마린과 비밀을 공유하게 되는데...?! 절대로 교차할 리 없던 두 사람의 세계가 움직이기 시작한다!','https://image.tmdb.org/t/p/w500/7r5Om5Ld6OzoRrXRROFiCTNpZFd.jpg',8.417,'https://image.tmdb.org/t/p/original/gWPK2RIVJ6i3myf7Xdw8DqlznT8.jpg','2022-01-09','その着せ替え人形は恋をする'),
(46,64196,'오버로드','애니메이션','가상 세계에서 현실처럼 플레이하는 체감형 게임, 통칭 DMMO-RPG의 전성기 2138년. 2126년에 발매된 《위그드라실》은 DMMO-RPG들 중에서도 방대한 맵과 엄청나게 높은 플레이어 자유도로 인해 국내에서 폭발적인 인기를 얻었고 DMMO-RPG의 붐을 일으킨 장본인이다. 그러나 12년이 지난 지금 조용히 서비스를 종료할 예정이었다. 위그드라실의 최강 마법사, 모몬가는 쓸쓸히 나자릭 지하대분묘에서 종료시간을 기다리고 있었다. 그러나 종료시간을 넘어도 로그아웃되지 않고, NPC들도 갑자기 의지를 가지기 시작하는데. 그의 앞에는 이제껏 본 적 없었던 이세계가 펼쳐지게 된다…!','https://image.tmdb.org/t/p/w500/7Tz5N2IFjjELjigqfQpz8UVaNew.jpg',8.459,'https://image.tmdb.org/t/p/original/q5WJxYTXNNJdEHxFCqd3S8pO4VA.jpg','2015-07-07','オーバーロード'),
(47,67075,'모브사이코 100','애니메이션','가공할 초능력의 보유자지만 보통의 삶을 고집하고 있는 인기가 많아지고픈 평범한 중학생 카게야마 시게오의 이야기를 그린 애니메이션','https://image.tmdb.org/t/p/w500/krBHtLnl6zLSmriYp8f7lpLlIoG.jpg',8.503,'https://image.tmdb.org/t/p/original/kP5duNJEbTfXpBs6CITsaZ88pQi.jpg','2016-07-12','モブサイコ100'),
(48,45950,'하이스쿨 DxD','애니메이션','신참 악마 잇세이의 머슴 인생, 파란만장한 시작!\n\n인기 없는 고등학생 효도우 잇세이에게 기적적으로 첫 여친이 생겼다! 그러나 그녀의 정체는 타천사였다!  그리고 첫 데이트에서 여친이 잇세이를 살해한다.. 죽어가는 잇세이를 구한 것은 학교 제일의 미소녀 리아스 그레모리 선배였다.\n\n그녀의 입에서 밝혀지는 충격적인 사실! “넌 악마로 전생했어. 날 위해서 일하도록 하렴!”\n\n그렇게 잇세이는 학교 제일의 미소녀 리아스 선배의 부하이자 사역마로 다시 태어난다!\n\n「절호조 학원 러브코미디 판타지, 배틀도 보여드립니다!」','https://image.tmdb.org/t/p/w500/yMYvz4vbKMIXb2IMYYi1GSlNaGx.jpg',8.503,'https://image.tmdb.org/t/p/original/oF8PNdntjZ7DUrAvnhNPPNRi0q6.jpg','2012-01-06','ハイスクールD×D'),
(49,72517,'어서 오세요 실력 지상주의 교실에','애니메이션','이 사회는 평등한가 아닌가. 진짜 \'실력\'이란 무엇인가.\n\n고도 육성 고등학교. 그곳은 철저한 실력지상주의를 내건 진학률과 취업률 100%를 자랑하는 학교이다.\n\n올해 입학해 1학년 D반에 소속된 아야노코지 키요타카. 하지만 학교는 \'실력지상주의\'라는 간판과는 정반대로 학생들에게 현금과 동일한 가치를 가진 포인트를 한 달에 10만엔 가량 주고선 수업이나 생활태도에 관해 방임주의로 일관한다.\n\n돈을 펑펑 쓰며 방탕하게 꿈만 같은 나날을 보내던 학생들. 하지만, 머지않아 그들은 학교 시스템의 진실을 알게 되어 절망의 늪에 빠져버리고 만다!\n\n낙오자가 모여든 D반에서 소년소녀들이 발견한 것은 과연 세계의 모순인가, 혹은 정당한 실력사회인가..','https://image.tmdb.org/t/p/w500/vE5TgFtcSCgLICbGXE0aNQXvbWF.jpg',8.424,'https://image.tmdb.org/t/p/original/c2sl2dLlyFFeb18pJtOpBD8cidr.jpg','2017-07-12','ようこそ実力至上主義の教室へ'),
(50,245842,'지팡이와 검의 위스토리아','애니메이션','어엿한 마도사를 꿈꾸고 마법학교에 입학한 소년 윌. 누구보다도 노력하는 그에게는 마도사로서 치명적인 약점이 있었다. 그것은 \'마법을 전혀 사용할 수 없다\'는 것. 동급생과 교사가 차가운 눈으로 바라보는 가운데 때로는 꺾일 것 같으면서도, 윌은 마음을 강하게 먹고 정진했다. 지팡이는 쓸 수 없지만 검을 사용해 마법 지상주의인 세계에서 싸워 나간다. 자신에게만 주어진 힘을 믿고. 그리고 소중한 사람과 한 약속을 지키기 위해. 열등생인 소년이 검으로 마법에 도전한다. 지팡이와 검이 교차하는 마검담이 지금 시작된다!','https://image.tmdb.org/t/p/w500/hcLU81mLtNR9ariY7Afsckfx9QB.jpg',7.993,'https://image.tmdb.org/t/p/original/n4VljCX22hbw3RwfxaY8FX8eLzN.jpg','2024-07-07','杖と剣のウィストリア'),
(51,82739,'청춘 돼지는 바니걸 선배의 꿈을 꾸지 않는다','애니메이션','사춘기 증후군. 불안정한 정신으로 인해 일어난다고 인터넷에서 화제인 불가사의한 현상. 에노시마에서 가까운 학교에 다니는 고등학교 2학년 아즈사가와 사쿠타는 사춘기 증후군이 일어난 소녀들과 만나게 된다. 예를 들면, 도서관에서 만난 야생 바니걸 정도. 바니걸의 정체는 고등학교 선배이자 활동을 중단한 연예인인 사쿠라지마 마이였다. 매력적인 마이의 차림에도 어째선지 주변 사람들은 그런 마이를 알아채지 못했다. 남들에게 보이지 않게 된 마이를 돕게 되면서 함께 보내는 시간이 많아지자, 사쿠타는 마이가 숨겨온 마음을 알게 되는데.  하늘과 바다가 반짝이는 마을에서 마음을 흔드는 소녀들과의 불가사의한 이야기가 시작된다.','https://image.tmdb.org/t/p/w500/s7qBgudeUEczJYEsO9vvRVUNnFP.jpg',8.517,'https://image.tmdb.org/t/p/original/8165gnzhyRbkKfm3WFBINdkDQBR.jpg','2018-10-04','青春ブタ野郎はバニーガール先輩の夢を見ない'),
(52,223564,'너를 너무너무너무너무 좋아하는 100명의 그녀','애니메이션','중학교에서 실연 100회를 달성한 아이죠 렌타로는 고등학교에서야말로 여자친구를!이라는 소원을 빌러 방문한 신사에서 갑자기 나타난 신으로부터 \'고등학교에서 만나게 될 \'운명의 상대\'가 \'100명\' 있다\'라는 말을 듣게 된다. 하지만 신이 말하길 운명의 상대와 만난 인간은 그 상대와 서로 \'사랑\'해서 \'행복\'해지지 않으면 \'죽음\'을 맞이한다고 하는데... 차례차례 기다리고 있는 운명의 상대와의 만남, 어떻게 할 것인가 \'렌타로?\' 어떻게 될 것인가 \'100명의 그녀?!\'','https://image.tmdb.org/t/p/w500/8dnsvARbJbrWSKsZzz8wBEpKLwU.jpg',8.201,'https://image.tmdb.org/t/p/original/shXdGFZIEaSmiOkVW2BeEaPihuA.jpg','2023-10-08','君のことが大大大大大好きな100人の彼女'),
(53,119495,'어둠의 실력자가 되고 싶어서!','애니메이션','“어둠의 실력자” 그것은 주인공도 라스트 보스도 아니다. 평소에는 실력을 숨기고 모브에 투철하고, 이야기에 어둠으로 개입해 은밀하게 실력을 보여주는 존재. 이『어둠의 실력자』를 동경해, 매일 모브로서 눈에 띄지 않고 생활하면서, 힘을 찾아 정진하던 소년은 사고로 목숨을 잃고 이세계로 환생한다. ‘시드 카게노’로 다시 태어난 소년은, 이를 다행으로 여기고 이세계에서 ‘어둠의 실력자’라는 설정을 즐기기로 한다. ‘망상’으로 만들어낸 『어둠의 교단』을 쓰러뜨리기 위해(장난으로) 암약하고 있었는데, 아무래도 정말로 망상으로 만들어낸 『어둠의 교단』이 존재하는데……? 게다가 별생각 없이 부하로 삼은 소녀들의 『착각』으로 인해 ‘시드’를 숭배하고, ‘시드’는 본인도 모르는 사이에 진짜 『어둠의 실력자』가 되어간다. 그리고 ‘시드’가 이끄는 어둠의 조직 『섀도우 가든』은, 이윽고 세상의 어둠을 멸망시켜 간다────!!','https://image.tmdb.org/t/p/w500/51hKUMfLjaFdw3uAoXeg5q9mA1d.jpg',8.077,'https://image.tmdb.org/t/p/original/htD5SJpPOvkmAowU80KrWnN59WO.jpg','2022-10-05','陰の実力者になりたくて！'),
(54,34742,'To LOVE 트러블','애니메이션','평범하고 순진한 고등학생 리토. 그런 그에게 어느 날 미모의 소녀 라라가 갑자기 나타나면서 평온했던 그의 일상은 순식간에 180도 바뀌게 된다. 우주에 있는 데빌루크 별의 세상물정을 전혀 모르는 왕녀인 라라는 다른 이들의 시선에 개의치 않고 리토를 끌어안거나 샤워를 하다 옷을 걸치지 않고 욕실 밖으로 나와 리토를 당황하게 하는 등 갖가지 사건을 벌인다. 한편 리토는 중학교 시절부터 좋아해온 동급생 소녀 하루나에게 자신의 마음을 전하지 못한채 계속 속앓이를 하고 있는데...','https://image.tmdb.org/t/p/w500/bOJRApP65FO787UWqRQqXCe1XNs.jpg',8.2,'https://image.tmdb.org/t/p/original/61vXR9xfgNqidYkBruRXhRTlVzI.jpg','2008-04-04','To LOVEる -とらぶる-'),
(55,223500,'윈브레 -WINBRE-','애니메이션','성적은 최저, 싸움은 최강. 불량 학교로 이름 높은, 후우린 고교. 그 정상을 차지하기 위해, 마을 밖에서 온 고교 1학년 사쿠라 하루카. 하지만, 현재의 후우린 고교는 ‘보후우린’이란 이름으로 마을을 지키는 집단이 돼 있는데!? 불량 고교생 사쿠라의 영웅 전설, 지금 개막!','https://image.tmdb.org/t/p/w500/sHriU7cwFxz1tcwAZSJlMOTy7QK.jpg',8.13,'https://image.tmdb.org/t/p/original/czrAvoN103RYYX8lhkZPs2zgnkl.jpg','2024-04-05','WIND BREAKER'),
(56,37305,'소울이터','애니메이션','사신 무기장인 전문학교. 그곳의 학생인 \'장인\'과 \'무기\'.\n\n그들의 의무는 단 하나! \'99개의 인간 영혼\'과 \'1개의 마녀 영혼\'을 무기에게 먹여, 사신님의 무기가 될 \'데스사이스\'를 만드는 것-!!','https://image.tmdb.org/t/p/w500/hI5AhxFTSFabTG7Fvhczyb5ZIh8.jpg',7.788,'https://image.tmdb.org/t/p/original/yOkNYWCOWLh3HFtUlo3QT1g5pHG.jpg','2008-04-07','ソウルイーター'),
(57,131041,'블루 록','애니메이션','세계 제일의 에고이스트가 아니면, 세계 제일의 스트라이커가 될 수 없다. 일본을 월드컵 우승으로 이끌 스트라이커를 육성하기 위해 일본 축구 연맹은 어떤 계획을 내세웠다. 그 이름은 \'블루 록(푸른 감옥)\' 프로젝트. 그렇게 해서 모인 300명의 고등학생들. 거기에다 모두 FW(포워드) 포지션이었다. 299명의 축구 생명을 희생시켜 탄생할, 일본 축구에 혁명을 불러일으킬 스트라이커는 과연? 지금, 역사상 가장 뜨겁고 정신 나간 축구 애니메이션이 개막한다.','https://image.tmdb.org/t/p/w500/tqiDHyR3YoIq4h0taoodUwp78Uz.jpg',8.259,'https://image.tmdb.org/t/p/original/seMRyWVwIVBWbC9xaMzDMZJ8fUH.jpg','2022-10-09','ブルーロック'),
(58,60863,'하이큐!!','애니메이션','히나타 쇼요는 우연히 춘고 대회의 배구 경기를 보다 코트 위에서 활약하는 \'작은 거인\'에 이끌려 배구를 시작하게 된다. 그로부터 3년 뒤 중학교 처음이자 마지막 공식 경기에서, 히나타는 \'코트 위의 제왕\'이라는 별명을 지닌 천재 세터 카게야마 토비오가 속한 키타가와 제1 중학교와 맞붙어 참패당한다. 이후 배구 명문교에 진학했을 카게야마에게 리벤지하겠다는 일념으로 \'작은 거인\'이 다녔던 카라스노 고교에 입학하지만, 그곳에서 웬일인지 카라스노에 입학한 카게야마와 마주치게 된다.카게야마가 카라스노 고교에 가게 된 이유는 공부를 못해서 간것도 있지만 시라토리자와에 지원하였다가 떨어져서이다.','https://image.tmdb.org/t/p/w500/3hbEgDctBcvM15uIH1RHR4cvWIv.jpg',8.6,'https://image.tmdb.org/t/p/original/zr1MDQCPVB5uJEHxiO6Tukn4OjH.jpg','2014-04-06','ハイキュー!!'),
(59,902,'유희왕 듀얼몬스터즈','애니메이션','게임의 역사, 그것은 지금으로부터 5천년 전, 고대 이집트까지 거슬러 올라간다.\n\n고대에 행해진 게임은 인간이나 왕의 미래를 예언하고 운명을 결정하는 마술적인 의식이었다. 그것들은 \'어둠의 게임\'이라 불렀다.\n\n그리고, 지금 천년 퍼즐을 풀고 어둠의 게임을 계승한 소년이 있었으니...\n\n빛과 어둠, 두 개의 마음을 가진 소년. 사람들은 그를 유희왕이라 부른다.','https://image.tmdb.org/t/p/w500/faqEzs9roS3MfPJVr5uWMTI1qsU.jpg',8.3,'https://image.tmdb.org/t/p/original/gJYZBM200Flldo6im3EEdXslR1j.jpg','2000-04-18','遊☆戯☆王デュエルモンスターズ'),
(60,40424,'이니셜D','애니메이션','1998년 4월 Fuji TV에서 방영을 시작한 애니메이션. 후지와라 타쿠미는 중1때부터 아버지 후지와라 분타 때문에 AE86으로 강제로 두부배달을 시작, 5년 이상 군마의 아키나 고개를 주행해 왔다. 무료함을 달랠 심산으로 두부를 싣지 않은 내리막길에서는 마음껏 속도를 내고 빨리 돌아오기 때문에 5년이란 세월 동안 말도 안 되는 테크닉을 몸으로 익히게 되었다. 어느 날 갑자기 아키나 고개에 등장한 아카기 레드선즈의 타카하시 케이스케와의 하시리야 배틀을 통해 공도 레이싱의 세계에 눈뜨고, 쟁쟁한 드라이버들과의 배틀을 통해 점차 레이서로서 성장해 나간다.','https://image.tmdb.org/t/p/w500/8TYwL6V8RA6kSi8PmBk703200Pm.jpg',8.011,'https://image.tmdb.org/t/p/original/zBIIyH8yfdlfvvpEiG9PLwoVXc6.jpg','1998-04-18','頭文字D'),
(61,63926,'원펀맨','애니메이션','취미로 히어로를 하기 시작한 남자 사이타마. 그는 3년간의 특훈으로 무적 파워를 손에 넣었다. 하지만 너무 강해진 나머지 어떤 강적을 상대해도 원펀치로 끝나버렸다. 압도적인 힘이란 재미없는거야... 그런 정열과, 모발을 잃은 평온한 최강 히어로 앞에 새로운 강적이 나타난다. 오늘이야말로 진심을 다해 싸울 수 있을 것인가!?','https://image.tmdb.org/t/p/w500/sV5D7lM4isMmK1gNSv2SglqYnni.jpg',8.371,'https://image.tmdb.org/t/p/original/s0w8JbuNNxL1YgaHeDWih12C3jG.jpg','2015-10-05','ワンパンマン'),
(62,99071,'회복술사의 재시작','애니메이션','\'치유\'의 용사로서 각성해서 다른 용사들과 세계를 구하기 위해 모험을 떠난 소년 케얄.\n\n하지만 전투능력이 없는 회복술사에게는 용사들에게 능력을 착취당하고 학대받는 나날이 기다리고 있었다.\n\n자유과 존엄을 빼앗기고 자아조차도 잃어가던 케얄은 어느 날, 제정신을 되찾고 \'힐\'의 진실을 깨닫는다.\n\n\'힐\'은 단순한 치유가 아니다. \'힐\'은 세계를, 인간을 근원에서부터 뒤흔들 수 있는 힘이다.','https://image.tmdb.org/t/p/w500/jUf0UYZUbfdiQELhnr6VyGe6Gc6.jpg',8.306,'https://image.tmdb.org/t/p/original/injrIOMNCQv4kTNX6hWa1QlyKoK.jpg','2021-01-13','回復術士のやり直し'),
(63,207468,'괴수 8호','애니메이션','일상적으로 괴수가 사람들을 위협하는 세계. 괴수를 토벌하는 「일본 방위대」 입대를 지망하던 히비노 카프카는, 언제부턴가 그 꿈을 포기하고 괴수 전문 청소업자로서 일하고 있었다. 「둘이서 괴수를 전멸시키자」 어린 시절 그렇게 함께 맹세한 소꿉친구 아시로 미나가 제3부대 대장으로서 각광을 받고 있는 가운데, 그녀와 함께 싸울 수 없는 카프카는 자신이 한심하게 느껴졌다. 하지만, 방위대에 입대하려는 이치카와 레노와의 만남을 계기로 멈춰있던 카프카의 시간이 다시 움직이기 시작하는데..!...','https://image.tmdb.org/t/p/w500/wBsGdFsrD9CL8xRphidx60EmgBE.jpg',8.436,'https://image.tmdb.org/t/p/original/htGeuCcNhlBe8GTx3izKOsd8frw.jpg','2024-04-13','怪獣８号'),
(64,203737,'【최애의 아이】','애니메이션','지방 도시에서 일하는 산부인과 의사 고로. 어느 날, \'최애\' 아이돌 \'B코마치\'의 멤버 아이가 그의 앞에 나타난다. 그녀는 어떤 금단의 비밀을 품고 있었는데… 그런 두 사람의 \'최악\'의 만남에서부터 운명이 움직이기 시작한다──.','https://image.tmdb.org/t/p/w500/zim3SB5YPcS6Hl2uLScJeW5bLIz.jpg',8.308,'https://image.tmdb.org/t/p/original/gArCVC4ML529WMCEqOXbALdQbUq.jpg','2023-04-12','【推しの子】'),
(65,30669,'유유백서','애니메이션','학교에서 나쁜 짓만 골라서 하는 걸로 악명 높은 불량소년 우라메시 유스케. 아이들은 그를 피해다니고 선생님들도 어찌할 바를 모른다. 그러던 어느 날 유스케는 한 꼬마아이를 살리려다 죽고 마는데... 하늘이 정해준 수명보다 일찍 죽은 유스케는 하늘에서 \'시련\'을 받고 세상에 다시 내려오게 된다.\n\n물론 유령으로...','https://image.tmdb.org/t/p/w500/4qnoZl1kQPBBMZBETaPDvdrazKb.jpg',8.454,'https://image.tmdb.org/t/p/original/uNM5dbnPJXJJs1eggepRWjSvdIR.jpg','1992-10-10','幽☆遊☆白書'),
(66,76075,'유루캠△','애니메이션','이는 어느 겨울 날의 이야기.\n\n시즈오카에서 야마나시에 이사 온 여고생 ‘카가미하라 나데시코’는 ‘천엔짜리 그림에 들어가 있는 후지산’을 보기 위해 자전거를 타고 모토스코까지 갔지만 공교롭게 날씨는 구름이 많다.\n\n후지산도 쳐다보지 못하고 지친 나데시코는 그 자리에서 곯아떨어지고, 깨어 나 보니 한 밤중-.\n\n돌아오는 길을 잃어 버린 와중에 솔로캠핑을 즐기는 여고생 ‘시마 린’을 만나게 된다.\n\n시린 몸을 따뜻하게 하기 위해 모닥불을 쬐는 두 사람.\n\n타닥타닥 장작 튀는 소리가 호숫가의 정적으로 스며들어 간다.\n\n모닥불에 둘러 앉아 카레 국수를 홀짝거리며 대화하는 나데시코와 린.\n\n이윽고 두 사람은 기다리던 순간을 맞는다.\n\n‘보였다… 후지씨…’ 나데시코와 린, 두 사람의 만남에서 비롯된 아웃도어계 여성 이야기.','https://image.tmdb.org/t/p/w500/1ZEldDcZFYcsnKysRSj003VjeNj.jpg',8.2,'https://image.tmdb.org/t/p/original/cm3lmKnEAYLs2eJmn4AcFIu18X4.jpg','2018-01-04','ゆるキャン△'),
(67,50712,'흑집사','애니메이션','여왕의 명을 받고 영국의 온갖 어두운 일면을 처리하는 악의 귀족 \'팬텀하이브 가문\'.\n\n그런데 당주의 아들 10살 생일날, 누군가의 손에 의해 구성원은 모두 참혹하게 살해당하고 저택엔 불이 질러진다.\n\n하지만 당주의 어린 아들 시엘 팬텀하이브만은 죽은게 아니라 납치당해 학대받고 있었고 생과 사의 기로에서 살기 위해 복수를 위해 악마인 세바스찬 미카엘리스와 영혼을 대가로 계약을 맺는다.\n\n그리고 돌아온 시엘은 팬텀하이브가의 유일한 생존자로서 어린 나이에 당주자리를 이어받아 여왕의 명을 수행하는 한편 팬텀하이브가를 그렇게 만든 범인을 찾기 시작하는데...','https://image.tmdb.org/t/p/w500/naBVOWX9vjm7eLWb6We05dgvWA6.jpg',7.753,'https://image.tmdb.org/t/p/original/5U0dYTkHXPhoExNnEm5iKrpDqtr.jpg','2008-10-02','黒執事'),
(68,97525,'불멸의 그대에게','애니메이션','불사는 최초에 지상에 던져진 \'구체\'였다.\n\n가지고 있던 것은\n\n\'자극을 받은 생물의 모습으로 변할 수 있는 능력\'과 \'죽어도 재생할 수 있는 능력\'.\n\n구체에서 돌, 늑대, 그리고 소년으로 모습을 바꾸지만 아기와 다름없이 아무것도 알지 못한 채 방황한다.\n\n이윽고 만나는 사람들로부터 살아가는 법을 배우고 따뜻한 감정을 알게 되어\n\n인간을 모방해서 성장해 가는 불사.\n\n숙명의 적인 노커와의 처절한 싸움, 소중한 사람과의 이별...\n\n아픔을 견디면서 자신의 삶을 선택하고 강하게 살아가는 불사의 영원한 여행을 그린다....','https://image.tmdb.org/t/p/w500/gM80dPt22btCRv1OcaQnhCfLq9v.jpg',8.2,'https://image.tmdb.org/t/p/original/fBWZQOPl5CuYxdXRb0uNVX8mgcG.jpg','2021-04-12','不滅のあなたへ'),
(69,117465,'지옥락','애니메이션','에도시대 말기. 이와가쿠레 최강의 닌자로 이름을 떨쳤으나 닌자의 세계에서 발을 빼려다 붙잡혀 사형수가 된 ‘가비마루’는 극락 정토라 소문난 섬에서 ‘불로불사의 약’을 가지고 오면 무죄 방면될 수 있다는 말을 듣는다. 가비마루는 사랑하는 아내와 재회하기 위해 참수 집행인 ‘야마다 아사에몬 사기리’와 함께 선약이 있다고 하는 섬으로 향한다. 그러나 같은 이유로 선약을 찾고 있는 사형수들이 섬에 상륙한 가비마루와 사기리의 앞을 가로막는다. 그리고 섬에 숨어 있는 미지의 생물, 인공적이고 섬뜩한 석상, 섬을 통솔하는 선인들… 수수께끼가 많은 섬에서 과연 가비마루는 선약을 찾아내어 살아서 돌아갈 수 있을 것인가!?','https://image.tmdb.org/t/p/w500/d5hzkYaO1h7UjH3Q0MRfyGVXjLi.jpg',8.186,'https://image.tmdb.org/t/p/original/vjiIuR3XGpoGSumQ7DziPAmxIYR.jpg','2023-04-01','地獄楽'),
(70,45782,'소드 아트 온라인','애니메이션','2022년. 인류는 마침내 완전한 가상 공간을 실현했다. 모든 게이머가 꿈꿔왔던 VRMMORPG (가상 대규모 온라인 롤 플레잉 게임)  \"소드 아트 온라인\" 이 정식 가동을 시작한다. 주인공은 소드 아트 온라인 플레이어인 키리토.  그는 SAO의 세계에서 플레이를 만끽하던 중 다른 1만 명의 플레이어와 함께 게임 마스터의 무자비한 선고를 듣는다. 100층까지 있다는 부유성 아인크라드의 정상을 정복해 게임을 클리어 하지 못하면 로그아웃을 할 수 없다고… 그리고 게임 오버는 현실 세계에서 \"죽음\"을 의미한다고... 키리토는 재빨리 게임의 \'진실\'을 받아들이고 파티를 짜지 않는 솔로 플레이어로 끝이 보이지 않는 사투에 몸을 던진다.','https://image.tmdb.org/t/p/w500/j1Ne28nNQrv6Fq51AppcBdJPNhf.jpg',8.2,'https://image.tmdb.org/t/p/original/z7QKvQbOrIhp9uOT63l9dIgHJrb.jpg','2012-07-08','ソードアート・オンライン'),
(71,12536,'유희왕 듀얼몬스터즈 GX','애니메이션','듀얼 아카데미라는 듀얼학교에서 벌어지는 이야기를 그린 애니메이션','https://image.tmdb.org/t/p/w500/y2omj7iTgJlztvfAxkeBNKdK5NS.jpg',7.883,'https://image.tmdb.org/t/p/original/1cKV1MXj1D9NJBXS1zlmkEYqGgY.jpg','2004-10-06','遊戯王デュエルモンスターズＧＸ'),
(72,240411,'단다단','애니메이션','영매사 집안에 태어난 여고생?모모＜아야세 모모＞와, 같은 학교에 다니는 오컬트 매니아 오카룽<타카쿠라 켄>. 모모가 반에서 괴롭힘당하던 오카룽을 도와준 것을 계기로 이야기를 하게 된 두 사람이었지만 \'유령의 존재는 믿지만 우주인의 존재는 부정\'하는 모모와, \'우주인의 존재는 믿지만 유령의 존재는 부정\'하는 오카룽은 말다툼을 하게 된다.서로 존재를 부정하는 우주인과 유령의 존재를 믿게 만들기 위해 모모는 UFO 스폿인 폐병원에, 오카룽은 심령 스폿인 터널에 가게 된다.그곳에서 두 사람은 이해를 초월하는 압도적인 괴기와 조우한다. 궁지에 몰려 숨겨진 힘을 각성한 모모와 저주의 힘을 손에 넣은 오카룽이 닥쳐오는 괴기에 도전한다!운명적 사랑도 시작!?오컬틱 배틀 & 청춘 이야기, 개막!...','https://image.tmdb.org/t/p/w500/ztR1BJbFx5XZgbtX2Ii2y7jjT9X.jpg',8.538,'https://image.tmdb.org/t/p/original/uNTrRKIOyKYISthoeizghtXPEOK.jpg','2024-10-04','ダンダダン'),
(73,96316,'여친, 빌리겠습니다','애니메이션','20살의 글러먹은 대학생 키노시타 카즈야.\n\n처음으로 여자친구와 키스를 딱 한 번 했는데, 겨우 한 달 만에 녹초가 되어버렸다.\n\n‘아...싫어... 이제 뭔가 전부 싫다’\n\n자포 자기하게 된 카즈야는, ‘어떤 방법’을 사용해서 여자아이와 데이트를 하게 되고. 약속장소에 가게 되는데,\n\n“네가 카즈야군이야?”\n\n부슬부슬 검은 머리를 귀에 넘기고 카즈야의 얼굴을 살펴보는 미소녀, ‘미즈하라 치즈루’는 미소를 지었다.\n\n한 번의 렌탈로 빛나기 시작하는 ‘리얼’이 있는 러브X두근 MAX의 무대포 러브 스토리!','https://image.tmdb.org/t/p/w500/uLrEqu1JkSMe4AN7IMMBEfhFAXE.jpg',8.3,'https://image.tmdb.org/t/p/original/ullfy98STkno11rDGi44SK6llwx.jpg','2020-07-11','彼女、お借りします'),
(74,46261,'페어리 테일','애니메이션','온 세상에 수없이 존재하는 마도사 길드. 마도사 길드란, 불가사의한 힘인 마법을 자유자재로 다루며 다른 이들을 도우는 자들인 \'마도사\'(魔度師)들이 모여 활동하는 일종의 모임 조직을 뜻한다. 훌륭한 마도사를 목표로 하는 소녀 루시는 엉뚱한 일로부터 불을 먹고 불을 토해, 불을 휘감아 싸우는 드래곤 슬레이어 나츠와 만나, 나츠가 소속하는 길드〈페어리테일〉에 가입한다.','https://image.tmdb.org/t/p/w500/b754UG0T1o0AkZ5IokiY3pIa3BS.jpg',7.912,'https://image.tmdb.org/t/p/original/lT8CUfNOkBQW9oPda2T5UPzVquM.jpg','2009-10-12','FAIRY TAIL'),
(75,42573,'슬램덩크','애니메이션','살짝 불량하면서도 단순무식한 고등학교 1학년생, 강백호. \'농구\'의 \'ㄴ\'자도 몰랐던 그가 좋아하는 여학생에게 잘 보이겠다는 일념으로 농구부에 들어간다. 그리고 농구를 조금씩 배워가면서 그 매력에 점점 빠져든다.','https://image.tmdb.org/t/p/w500/tl44cjAK0UiQSH6aRLs1ActnGEp.jpg',8.7,'https://image.tmdb.org/t/p/original/dEANXnVRmFkSD8jcJlZ0oy8EnB1.jpg','1993-10-16','スラムダンク'),
(76,61374,'도쿄 구울','애니메이션','\"군집 속에 섞여 인간을 사냥하고 그 죽은 고기를 먹는 괴인.\n\n우리들은 그들을... 구울이라 부른다.\"\n\n갑작스런 사고로 죽을 고비를 맞은 주인공이 이식을 받아 특별한 존재가 되어 구울 사이에서 방황하는데...','https://image.tmdb.org/t/p/w500/nkDtqLGG7J7L7YoodfCSWFUT65l.jpg',8.259,'https://image.tmdb.org/t/p/original/jnwRlthXIgJB75Mt9GEl93Dczki.jpg','2014-07-04','東京喰種トーキョーグール'),
(77,1429,'진격의 거인','애니메이션','2013년 4월 MBS에서 방영을 시작한 애니메이션. 100여 년 전 갑자기 나타난 거인들에 의해 멸종 위기에 처한 인류는 거대한 벽을 쌓고 그 안에서 살아가고 있다. 에렌은 바깥 세계를 동경하며, 언젠가 저 방벽 밖으로 나가겠다는 꿈을 키우고 있었다. 그러던 어느 날, 60m가 넘는 초대형 거인의 등장으로 벽은 무너지고, 거인들이 벽 안으로 들어와 사람들을 잡아먹기 시작한다. 절규와 죽음으로 가득한 절망적인 상황에서 거인에게 어머니 카를라를 비롯한 소중한 사람들을 빼앗긴 엘런은 복수를 맹세하고, 사무친 복수심을 원동력으로 삼아 만 12세에 훈련병단의 훈련병으로 지원한다.','https://image.tmdb.org/t/p/w500/kTYFXRdvo7GZWULKjeD4YZ929NC.jpg',8.681,'https://image.tmdb.org/t/p/original/rqbCbjB19amtOtFQbb3K2lgm2zv.jpg','2013-04-07','進撃の巨人'),
(78,20353,'꼬마마법사 레미','애니메이션','얼빠져서 여동생에게도 바보소리를 듣는 자칭〈세계제일불행한 미소녀〉인 초등학교 3학년생 하루카제 도레미(도레미). 마녀를 동경하고, 좋아하는 사람에게 고백할 용기를 마법으로 손에 넣고 싶어했던 그녀는, 이상한 곳에서 진짜 마녀인 마조리카와 만나게 된다.\n\n마녀 개구리가 되어버린 마조리카를 원래대로 돌려놓기 위해서, 도레미는 친구인 후지와라 하즈키(장메이), 세노 아이코(유사랑) (후에는 도레미의 여동생인 하루카제 폿프(도또미)도 합류.)와 함께 초보마법사가 되어서 수행에 힘써간다.\n\n초보마법사으로서 수행을 해나가던 세 사람은, 우연하게도 인간계에 잠복해 있는〈배드아이템〉이라고 하는 것을 찾아낸다. 이것은, 예전에 마법계에서 봉인되었던〈배드카드(악의 카드)〉가 붙은 것으로, 가진 사람의 소원과는 정반대인 불행을 가져온다. 세 사람은 마법계인 여왕님으로부터 악의카드의 회수를 의뢰받게된다.','https://image.tmdb.org/t/p/w500/yODQ7MDKMbvc9H7T06CCDTdzgeX.jpg',8.3,'https://image.tmdb.org/t/p/original/zJi8eaweBRbCjQU5C1HxucUCW6i.jpg','1999-02-07','おジャ魔女どれみ'),
(79,35894,'갓슈벨!!','애니메이션','\"얼간이 근성은 내가 때려 고쳐주마!\" 친구 만들기 작전 실시!\n\n머리가 너무 좋은 탓에 반에서 홀로 겉돌던 중학생 키요마로. 그의 집에 찾아든 것은 기묘한 주문이 적혀있는 수수께끼의 \'붉은 책\'과 불가사의한 꼬마 \'갓슈\'!\n\n갓슈의 숨겨진 힘 때문에 키요마로의 운명은 크게 바뀌기 시작하는데….','https://image.tmdb.org/t/p/w500/bQhmlSsqGCRn2Z896y6hY5DtDxk.jpg',8.5,'https://image.tmdb.org/t/p/original/n4MfPSRk5PzHeVrm43NHam8oH5d.jpg','2003-04-06','金色のガッシュベル!!'),
(80,890,'신세기 에반게리온','애니메이션','서기 2000년, 남극에 거대한 운석이 추락하며 미증유의 재난 세컨드 임팩트가 일어난다. 해수면의 상승, 천재지변, 경제붕괴, 민족분쟁, 내란 등으로 세계 인구는 반으로 격감된다. 2015년, 지구가 겨우 회복의 기미를 보이기 시작할 무렵 인류에겐 또 다른 위기가 닥쳐온다. 하나씩 모습을 드러내는 정체 불명의 거대 전투병기 군단 사도. 사도의 출현에 대항하기 위하여 인류는 E계획에 의해 탄생한 생체 전투병기 에반게리온을 개발하고 3대의 기체로 사도를 막아내려 하는데...','https://image.tmdb.org/t/p/w500/k3NQ7gVfnNPWbdCgg0x0Tv8CNNN.jpg',8.568,'https://image.tmdb.org/t/p/original/z2RumCOIZ6HO3oMvfINzZlFnPAw.jpg','1995-10-04','新世紀エヴァンゲリオン'),
(81,91801,'마계학교! 이루마군','애니메이션','14세 소년인 주인공 \'스즈키 이루마\'은, 어느 날 부모님의 금욕으로 인해 악마에게 팔려버린다\n\n한편, \'이루마\'를 구입한 대악마 \'설리번\'은 자손이 없어 그에게 손자가 되어달라고 부탁한다\n\n그렇게 \'설리번\'이 이사장으로 지내고 있는 마계 학교에 이사장 손자 겸 특기생으로.\n\n입학하게 된 \'이루마\'는 인간임을 숨기고 악마와 어울리는 학교생활을 하게 되고.\n\n여러 문제가 \'이루마\'를 덮쳐오지만. 지금까지 살아온 환경에 의해 솔직하고 부지런한 성격으로 극복해나가고.\n\n의도치 않게 학원 내에서 교우관계를 쌓으며, 유명인이 되는데...','https://image.tmdb.org/t/p/w500/x2NU6cyUiN5qlypOpSZPRRlsoTj.jpg',8.222,'https://image.tmdb.org/t/p/original/d8bAI2EDM7L2q94wDZfjb82KRoh.jpg','2019-10-05','魔入りました！入間くん'),
(82,27845,'테니스의 왕자','애니메이션','테니스부 명문인 \'세이슌\' 중학교에 입학한 료마. 그러나 입학한 날부터 테니스부 선배들로부터 못마땅한 눈초리를 받게 된다.\n\n테니스 채를 잡으면 박력과 카리스마가 넘치는 료마. 1학년은 대회에 나갈 수 없다는 관례를 깨고 선배들과 함께 대회에 나가게 된다.','https://image.tmdb.org/t/p/w500/cbooqJWoAYwT5NCHM19YTAeDJ2K.jpg',8.358,'https://image.tmdb.org/t/p/original/7apk7MDXON2zZ2ntXgaIusHrUNa.jpg','2001-10-10','テニスの王子様'),
(83,68854,'너에게 닿기를','애니메이션','겉으로 우울해 보이는 한 소녀가 인기 만점의 같은 학교 남학생 쇼타를 남몰래 좋아하며 벌어지는 이야기.','https://image.tmdb.org/t/p/w500/whZ4i3fx1CA9HZKmQmbPGkPUEWH.jpg',8.379,'https://image.tmdb.org/t/p/original/nh0BS0sLXozmkTpOe1Ve33MyxlK.jpg','2009-10-07','君に届け'),
(84,61445,'신격의 바하무트','애니메이션','사람과 신, 마족이 공존하는 세계, 미스탈시아. 그곳은 2천년 전 흑은의 날개를 가진 드래곤에 의해서 멸망의 위기를 맞이했었다. 그러나 종족의 벽을 뛰어넘은 신족과 마족, 인간의 협동으로 드래곤은 봉인되고 그 봉인의 열쇠는 절대 하나가 되지 못하도록 신과 마족에게 나뉘어 보관된다. 그러나 어느 날, 절대 훔치는 게 불가능한 신족의 열쇠를 한 소녀가 빼앗았고 세계의 균형은 천천히 무너지기 시작하는데.','https://image.tmdb.org/t/p/w500/oWjLPatirGO8AxizsTujUGGHjcu.jpg',7.653,'https://image.tmdb.org/t/p/original/asUFPHTGvdLvyyf3YxWZNvPWkoa.jpg','2014-10-06','神撃のバハムート'),
(85,83121,'카구야 님은 고백받고 싶어 ~천재들의 연애 두뇌전~','애니메이션','집안도 인망도 좋다!!\n\n장래가 기대되는 우수한 수재들이 모인 슈치인 학원!!\n\n그 학생회에서 만난 부회장 시노미야 카구야와 회장 시로가네 미유키는 서로에게 끌리고 있었지만, 아무 일도 없는 채로 반년이 경과!!\n\n프라이드가 강하고 솔직하지 못한 두 사람은, 귀찮게도 \"어떻게 상대방에게 고백을 받아낼 것인가\" 만을 생각하게 되어버렸다?!\n\n연애는 성취될 때까지가 즐겁다!!\n\n신감각 \"두뇌전\" 러브코미디 개전!','https://image.tmdb.org/t/p/w500/urzSiR7IiImAzyq2VyOJ1BtNChY.jpg',8.537,'https://image.tmdb.org/t/p/original/dJ8yrSokdTMnhKJw06MllSfCegb.jpg','2019-01-12','かぐや様は告らせたい～天才たちの恋愛頭脳戦～'),
(86,123528,'해골기사님은 지금 이세계 모험 중','애니메이션','눈을 떠 보니 MMORPG에서 자신이 사용하던 게임 캐릭터의 모습으로 이세계에 떨어진 ‘아크‘.\n\n그 모습은 외형이 갑옷, 내용물은 전신골격 \'해골기사\'였다.\n\n정체를 들키면 몬스터로 몰려 토벌 대상이 될 수 있다?!\n\n때문에 ‘아크’는 눈에 띄지 않게 용병으로 지내기로 결심하지만,\n\n눈앞에서 일어난 악행을 내버려 둘 만한 남자는 아니었다!\n\n해골기사님의 무자각  \'사회혁명\' 이세계 판타지!!','https://image.tmdb.org/t/p/w500/hd0uc0RMinOdquHzHmrfhLPDT2q.jpg',7.289,'https://image.tmdb.org/t/p/original/3srLRdCMd5IMLiyyHvdQNstee3W.jpg','2022-04-07','骸骨騎士様、只今異世界へお出掛け中'),
(87,114410,'체인소 맨','애니메이션','\'체인소의 악마\'포치타와 함께 데블 헌터로 사는 소년 덴지. 부모가 남긴 빚을 갚기 위해, 가난한 생활을 하던 중, 배신을 당해 죽임을 당하고 만다. 희미해지는 의식 속에서, 덴지는 \'포치타\'와 계약을 맺고, 악마의 심장을 가진 자 \'체인소 맨\'으로 되살아난다~!','https://image.tmdb.org/t/p/w500/eblIShqBgVPmRt86f4e02ouDNhE.jpg',8.516,'https://image.tmdb.org/t/p/original/5DUMPBSnHOZsbBv81GFXZXvDpo6.jpg','2022-10-12','チェンソーマン'),
(88,235758,'가끔씩 툭하고 러시아어로 부끄러워하는 옆자리의 아랴 양','애니메이션','쿠제 마사치카의 옆자리에 앉은 아랴 양은 언제나 쿠제에게 냉랭한 시선을 보낸다. 하지만 가끔씩 툭하고 러시아어로 부끄러워하는데……. 그 말을 마사치카는 흘려듣지 못한다. 놀랍게도 마사치카는 러시아어 리스닝이 원어민 수준이었던 것이다!! 눈치채지 못할 거라 생각하고 가끔씩 부끄러워하는 아랴 양. 그리고 그 의미를 이해하면서도 눈치채지 못한 척하는 마사치카. 히죽거림이 멈추지 않는 두 사람의 연애 행방은——!?','https://image.tmdb.org/t/p/w500/iugFRgKQNiKXIL0xAGCDiZss0p2.jpg',7.9,'https://image.tmdb.org/t/p/original/3197ZU1CWDjdFsmqvWPZGXAYaoi.jpg','2024-07-03','時々ボソッとロシア語でデレる隣のアーリャさん'),
(89,31736,'아이실드 21','애니메이션','심약한 성격의 주인공 코바야카와 세나가 우연히 미식축구부에 들어가게 되면서, 자신도 몰랐던 재능을 발견하게 되고 노력하게 되는 이야기를 그린 애니메이션','https://image.tmdb.org/t/p/w500/uPgu7WQclUGOkzRvun013X2aV82.jpg',8.4,'https://image.tmdb.org/t/p/original/fCpjDFze4ueeFEZkedQbePNFBTC.jpg','2005-04-06','アイシールド21'),
(90,66875,'논논비요리','애니메이션','전교생 5명인 아사히가오카 분교. 겨울이 끝나고 봄의 발소리가 들리는 산골에서 변함없이 느긋한 일상을 보내는 소녀들. 나물을 따고, 꽃 놀이도 하고, 물고기도 잡고...여유만만하고 싱그러운 그녀들의 계절맞이 방법을 보며, 어린 시절의 추억을 재발견 하는 건 어떨까요?','https://image.tmdb.org/t/p/w500/nWgEq6OoQssUq0onLgxq2iS2oH7.jpg',7.859,'https://image.tmdb.org/t/p/original/bP8MlXJwtDQC7sovNmt0AaLAZTb.jpg','2013-10-07','のんのんびより'),
(91,31724,'코드 기아스: 반역의 를르슈','애니메이션','거대국가 브리타니아 제국에 점령된 일본. ‘일본’이라는 이름을 말하는 것조차 금지된 그곳은 ‘AREA 11’이라는 이름으로 불리고 있었고, AREA 11의 주민들은 ‘일레븐’이라 불리며 제국이 임명한 통치관의 의해 통치를 받게 되었다. 막강한 군사력을 바탕으로 세계 각지에 AREA를 만들어가는 제국의 힘의 근원은 ‘나이트메어 플레임’이라 불리는 인간형 병기였다. 영원히 밝을 것처럼만 보였던 제국의 미래… 그러나 그 균열은 AREA 11의 한 소년으로부터 시작된다. 브리타니아인들을 위한 학교인 애슈포드 학원에 다니는 소년 를르슈는, 신주쿠 게토를 지나다 테러리스트와 브리타니아군 간의 싸움에 휘말려 든다. 우연히 브리타니아군에 소속되어 있던 옛친구 쿠루루기 스자쿠와 재회하게 되지만, 군대가 회수하려던 정체를 알 수 없는 소녀로 인해, 소녀와 를르슈를 지키려던 스자쿠가 총에 맞아 쓰러진다. 오열하는 를르슈에게 소녀는 ‘기어스’라는 능력을 부여해 준다. 자신의 목적을 달성하기 위해서라면 어떤 방법도 가리지 않는 를르슈. ‘기어스’의 힘을 손에 넣게 된 를르슈는 동생 나나리와 함께 자신의 이상을 위해 그 힘을 행사하려고 한다. 한편 정의를 지키며 자신의 길을 걸어가려 하는 쿠루루기 스자쿠는 브리타니아군의 병기 랜슬롯의 파일럿으로서 를르슈와 대립할 수밖에 없다.','https://image.tmdb.org/t/p/w500/mM5gcIex8pUknoGqrU07UNDQGtj.jpg',8.352,'https://image.tmdb.org/t/p/original/5hS2OIuZSKGkR8R5l3bY5zh04Ce.jpg','2006-10-05','コードギアス 反逆のルルーシュ'),
(92,56387,'북두의 권','애니메이션','핵전쟁의 발발로 황폐하고 문명이 붕괴한 무법 지대에서 평범한 사람들을 살해하는 난폭한 악당들이 날뛰는 서부극 같은 세계.\n\n북두신권의 전승자인 켄시로는 악당들과 사악한 권법가를 쓰러뜨려 사람들을 구하고, 공포로서 세상을 지배하려 하는 권왕 라오우에 도전하게 된다.','https://image.tmdb.org/t/p/w500/lokIbr6KuBGQKwAlUGTs8eY0u3D.jpg',8,'https://image.tmdb.org/t/p/original/hGRQM3wpjo3zrXN04wBEhWRK3ep.jpg','1984-10-11','北斗の拳'),
(93,256721,'가치아쿠타','애니메이션','범죄자 후손들이 모인 슬럼가에서 차별을 받으면서도 쓰레기를 주워 사는 루도.\n\n하지만 어느 날 몸에 익지 못한 죄를 뒤집어쓰고 누구나 두려워하는 \'나락\'으로 떨어지고 만다.\n\n나락에서 \'청소부\' 엔진과 만난 루도는 세계의 진실을 엿보고 사물에 목숨을 주고 힘을 끌어내는 능력을 발현시킨다.\n\n모든것은 똥같은 세상을 바꾸기 위해서--!!','https://image.tmdb.org/t/p/w500/RxuL7KuFoOzHC0htjtLGxJEGGx.jpg',8.517,'https://image.tmdb.org/t/p/original/mrapJp0qb6Fvo3IW9IrjCK9IgSo.jpg','2025-07-06','ガチアクタ'),
(94,35790,'카드캡터 체리','애니메이션','어느 날 밤 이상한 꿈을 꾸고 난 사쿠라는 아빠의 서재에서 꿈에서 본 책을 발견한다. 책 속에서 발견한 카드를 읽는 순간, 신비한 빛이 쏟아지면서 봉인된 카드의 파수꾼인 ′케로베로스′를 잠에서 깨운다. 그러나 카드 집을 열면서 크로우 카드의 봉인이 풀려 다시 카드를 모아야 하는데....','https://image.tmdb.org/t/p/w500/8jbo0LZ4cVrPI3IagPlizIwY7YT.jpg',8.61,'https://image.tmdb.org/t/p/original/w6a3S1E5p3UfFcP3jkieXlAY5mz.jpg','1998-04-07','カードキャプターさくら'),
(95,30980,'어떤 마술의 금서목록','애니메이션','초능력이 과학에 의해 해명된 세계.\n\n초,중,고, 대학이 몰려있는 ‘학원도시’는 초능력 개발을 필수 교육과정으로 지정하고 있기 때문에, 이곳 학생들은 초능력 지수로 능력을 평가받는다. 하지만 주인공 토우마는 신체검사에서 무능력자로 분류되어 하루하루 무의미하게 살고 있다. 그런 토우마 앞에 어느날 수녀복장을 한 소녀가 나타난다. 소녀는 자신의 이름이 금서목록(인덱스)이라며 마술사에 쫓기고 있다고 하고, 토우마는 과학과 마술이 교차하는 이세계로 빠져들게 되는데…','https://image.tmdb.org/t/p/w500/ttcZuM9WU4lTtRP22xa4FOEO6I9.jpg',7.515,'https://image.tmdb.org/t/p/original/73uQJImy9J9w93zFEh8JtdQVOQR.jpg','2008-10-05','とある魔術の禁書目録'),
(96,45952,'헌터X헌터','애니메이션','양친의 얼굴도 모른채 성장한 12살 소년 곤은 세계 제일의 헌터라 칭송받는 아버지와 만나기 위해 헌터가 되기로 결심한다. 헌터란 세계 최고의 직업으로 괴수나 범죄자를 잡거나 보물을 찾고, 새로운 자연현상을 발견하는 등 귀중하고 구하기 힘든 아이템을 찾아 생명을 거는 사람들을 뜻한다. 사람과 자연의 질서를 지키는 일을 기본적인 사명으로 삼는 헌터는 방대한 지식, 건강한 육체와 건전한 정신 그리고 강한 신념을 필요로 하는 세계적인 엘리트 집단이다. 헌터 자격증을 소진한 정식 헌터는 임무를 위한 모든 편의가 무상으로 제공되며, 부와 명성을 누릴 수 있는 최고 지위의 상징이기도 하다. 최고의 헌터를 발탁하기 위해 매우 까다로운 고난도의 헌터 자격시험에는 매년 수많은 헌터 지망생들이 각자의 신념을 위해 몰려든다. 자신을 키워준 미트 고모의 거센 반대에도 불구하고 마침내 곤은 헌터 자격시험 지원허락을 받아 여행길에 오른다. 곤은 헌터 시험에 도전하는 과정에서 키르아, 레오리오, 크라비카와 우정을 쌓게 되고, 일생 일대의 라이벌 히소카와도 만나게 된다. 어려운 시험을 통과하기 위해 힘과 재치, 순발력과 적응력은 기본이며, 친구를 위해 고통을 감수하는 우정 또한 필수요소이다. 다양한 능력을 지닌 사람들과 만나고 맞서면서 곤은 자신의 숨겨진 능력을 발굴해 내고 마침내 헌터 자격증을 따낸다. 그리고 천공격투장에서 격투를 하면서 육체의 잠재력을 이끌어 내는 기술 넨(念)을 배우게 된다. 과연 곤은 히소카와 대등한 능력을 지닌 헌터로 성장할 수 있을까? 그리고 아버지 진을 만날 수 있을까?','https://image.tmdb.org/t/p/w500/eobAuhCJA8oRp814V67WhezVXtQ.jpg',8.386,'https://image.tmdb.org/t/p/original/575sxZXNNulSlIz7DvtWH5r4lkC.jpg','1999-10-16','HUNTER×HUNTER'),
(97,43125,'길티 크라운','애니메이션','2029년, 돌연 발생한 아포칼립스 바이러스에 의해 대혼란에 빠진 일본. 결국 무정부 상태까지 돌입한 일본은 GHQ의 무력개입에 의해 그 통치하에 놓이게 된다.  일시적인 되찾은 평화. 그러나 그런 GHQ의 통치에 반기를 든 조직이 있었다. 그것이 레지스탕스 조직 `장의사`. 그리고 무대는 2039년. 평화로운 나날을 보내던 고등학생 오우마는 어느 날 우연히 한 소녀와의 만남을 가지게 된다. 그녀의 이름은 유즈리하 이노리.  웹상에선 막대한 영향력을 지닌 인기 가수.  그러나 다른 한편에선 일본해방을 위해 활동하는 `장의사`의 멤버. 그런 그녀와의 만남은 평화롭던 슌의 삶을 크게 바꾸어 놓게 된다.','https://image.tmdb.org/t/p/w500/x7O5mncnegqfEAp74mQfIhFbkMF.jpg',7.297,'https://image.tmdb.org/t/p/original/pe6kJStppV5CuEPD1dUhAOyG6LZ.jpg','2011-10-13','ギルティクラウン'),
(98,98034,'디지몬 어드벤처:','애니메이션','서기 2020년. 네트워크는 이제 인간의 삶에 있어서 없어서는 안 되는 것이 되었다. 하지만 인간은 모른다. 네트워크 너머 무한한 디지털 세계와 그곳에 사는 디지몬들이 있는지…. 수도권을 중심으로 대규모 네트워크 오류가 발생한다. 엉망으로 깜박이는 신호와 글자가 일그러진 야외 텔레비전. 사이버 테러라고 보도하는 뉴스. 주인공은 도쿄 근교의 타워 아파트에 사는 초등학교 5학년 야가미 타이치. 주말 여름 캠프를 준비하기 위해 혼자 집에 남아 있었지만, 시부야에 나간 어머니와 여동생 히카리가 정차할 수 없게 된 전차를 타고 있었다. 어머니와 동생을 돕기 위해 시부야로 돌진한 타이치지만, 역의 홈에 가는 그 순간 - 「선택받은 아이들」에 이상한 현상이 일어나고, 타이치는 디지털 세계로! 아이들은 파트너 디지몬을 만나 미지의 \"모험\"에 맞선다!','https://image.tmdb.org/t/p/w500/fINgW0uXJA1Ln6uOJmyLnuAec6P.jpg',7.557,NULL,'2020-04-05',NULL),
(99,31654,'디지몬 어드벤처','애니메이션','디지몬 세계의 평화를 지켜기 위해 노력하는 7명의 어린이와 일곱 디지몬의 이야기를 그린 애니메이션','https://image.tmdb.org/t/p/w500/gXerNlSAJQyG1opdmSAcCMN0Qnr.jpg',8.084,NULL,'1999-03-07',NULL),
(100,286791,'디지몬 비트브레이크','애니메이션','인간의 사고와 감정에서 태어나는 ‘e-펄스’는 AI 서포트 디바이스인 ‘서포타마’의 에너지원으로 활용되고 있었다. 눈부신 발전을 이룬 그 이면에서, 가공할 만한 괴물이 나타난다. e-펄스를 먹고 진화하는 생명체 ‘디지몬’이다. 차내일 서포타마에서 태어난 겟코몬과의 만남을 계기로, 비일상적인 세계로 휘말려 들어간다. 현상금 사냥을 생업으로 삼는 ‘글로잉 던’ 팀의 강우혁 일행과 함께 생활하면서 차내일은 새로운 결의를 다진다 인간과 디지몬이 함께 그려나갈 새로운 미래란......','https://image.tmdb.org/t/p/w500/bdKO0jm7Bwp6ft2JEg7DiVHCON3.jpg',7.7,NULL,'2025-10-05',NULL),
(101,9302,'디지몬 테이머즈','애니메이션','디지몬 시리즈 중 세번째 시리즈로 도쿄 신주쿠와 디지털 세계를 배경으로 디지몬들의 활약을 그린 애니메이션','https://image.tmdb.org/t/p/w500/pxv1aOcl5crXKaWN0dsUeqoSpfP.jpg',8.549,NULL,'2001-04-01',NULL),
(102,8991,'디지몬 프론티어','애니메이션','디지몬 프론티어','https://image.tmdb.org/t/p/w500/hzlqEyPhDURcCXi4snIOdlLdZjo.jpg',8,NULL,'2002-04-07',NULL),
(103,134843,'고스트 게임: 디지몬','애니메이션','새로운 기술이 발전한 가까운 미래. SNS는 홀로그램 고스트 라는 진위 불명의 괴기 현상이 소문으로 떠돌고 있었다. 아무도 모르는 세상 뒤편의 이야기를 그린 애니메이션','https://image.tmdb.org/t/p/w500/xtEbuN4N6fvTG01GAFdCUQYBHa2.jpg',7.4,NULL,'2021-10-03',NULL),
(104,68099,'디지몬 유니버스 어플리 몬스터즈','애니메이션','항상 자신을 들러리 캐릭터라고 생각하던 바다는 어느 날 우연히 어플드라이브를 손에 넣고 서치몬과 만나게 된다. 바로 그때 메시지몬이란 어플몬에 의한 소동이 벌어지고 바다는 사람들을 돕기 위해 서치몬과 함께 주인공으로서 싸워나가기로 결심한다.','https://image.tmdb.org/t/p/w500/ka7l04z9O9Jghp0RAsBOYLimil4.jpg',8.3,NULL,'2016-10-01',NULL),
(105,21918,'달빛천사','애니메이션','시한부 루나에게 나타난 사신 콤비의 도움으로 그토록 바라던 가수활동을 할 수 있게 되며 벌어지는 이야기','https://image.tmdb.org/t/p/w500/AecYTAKiDXj8z2Sa1ccD5LDtzGm.jpg',7.8,NULL,'2002-04-06',NULL),
(106,54241,'슈가슈가룬','애니메이션','쇼콜라와 바닐라는 마계의 차기 여왕 후보로 라이벌 관계이면서도 굉장히 친한 친구 사이이다. 그러던 어느 날 두 사람은 차기 여왕을 뽑는 시험을 치르기 위해 인간계로 긴 여행을 떠난다. 시험의 내용은 인간의 하트(자신을 향한 마음의 결정)를 보다 많이 모으는 것! 인간계의 학교로 동시에 전학을 온 두 사람은 첫 날부터 인간의 하트를 되도록 많이 모으려고 노력하지만, 어째 내성적인 성격의 바닐라에 비해 마계 최고의 인기녀인 쇼콜라는 인간들의 사랑을 전혀 받지 못한다. 게다가 ’피에르’란 수수께끼의 남자에게 사랑을 느끼고 마는 쇼콜라. 인간과는 달리 마녀는 사랑에 빠지면 하트를 빼앗겨 영혼을 영원히 빼앗기고 만다!! 과연 쇼콜라는 자신의 하트를 지킬 수 있을 것인가? 그리고 차기 여왕 자리의 행방은..??','https://image.tmdb.org/t/p/w500/xdlCDOZtHWJ1fH4YwuwIktoFOeQ.jpg',5.9,NULL,'2005-07-02',NULL),
(107,63164,'개구리 중사 케로로','애니메이션','퍼렁별 침략을 위해 찾아온 개구리 우주인의 이야기','https://image.tmdb.org/t/p/w500/6Br7tLfECdcFHYlKcPAMY7RWCTs.jpg',7,NULL,'2004-04-03',NULL),
(108,60656,'케로로팝','애니메이션','두꺼비 성운 58번 혹성 케론성으로부터 지구의 침략을 목적으로 군대가 파견되었다. 그 선발대로써 케로로 군단(케로로, 타마마, 기로로, 쿠루루, 도로로)의 5명의 병사로 이루어진 우주침공 특별군대가 지구로 오게 된다.','https://image.tmdb.org/t/p/w500/xiuePP7GqmHERw0ZIvyHhWBENOi.jpg',7,NULL,'2014-03-22',NULL),
(109,318918,'LEGO 원피스','애니메이션','2부작 레고 스페셜. 자신이 크루에 합류하기 전, 이스트 블루에서 그랜드 라인으로 이어진 밀짚모자 일당의 여정을 우솝이 과장된 이야기로 풀어낸다.','https://image.tmdb.org/t/p/w500/j5l5t8WhFVTW8eErIgJ6u6005gG.jpg',0,NULL,'2026-09-29',NULL);
