INSERT INTO `works_creativework` VALUES
(1,'최애의 아이','illustration','아이 그렸서요','막 맘에 들진 않지만 ..\r\n3시간컷낸 그림(귀찮아서 채색안한건 안비밀 ㅋㅋ)','works_images/최애의아이.jpg',814,'2026-07-15 09:47:17.170380','2026-07-15 09:47:25.935438',1,'published',1),
(6,'진격의 거인','cosplay','리바이 증명사진','보정 없고 리바이 코스프레하고 증명사진 찍어 봤는데 어떤가요..!','works_images/2리바이.jpeg',18438,'2026-07-22 07:47:47.869705','2026-07-23 05:57:58.693871',30,'published',1),
(7,'주술회전','illustration','죽어가는 도쿄.. 그 위에 스쿠나와 후시구로 메구미','제가 손재주가 좋다는 말을 많이 들어서연!!@  하핫','works_images/1스쿠나.jpg',13129,'2026-07-22 07:53:09.992370','2026-07-23 05:59:23.593803',31,'published',1),
(8,'원피스','illustration','너 내 도돋돋도돋도도도','조로 제가 그렸지만 너무 섹시하지 않나요..\n저만 보기 아까워서 공유합니다 !!_!!','works_images/1원피스_.jpeg',526,'2026-07-22 07:56:57.125506','2026-07-22 07:56:57.125528',32,'published',1),
(9,'진격의 거인','illustration','心臓を捧げよ','!','works_images/1ㅈㄱㄱ_ㄱㄱ2.jpeg',372,'2026-07-22 08:03:22.188191','2026-07-23 06:00:23.912189',33,'published',1),
(10,'진격의 거인','cosplay','기행종 중에서 내가 제일 잘나가','0-0','works_images/2기행종.jpeg',317,'2026-07-22 08:08:46.550175','2026-07-23 05:54:56.642311',35,'published',1),
(11,'원피스','cosplay','원피스의 주요  주인공','안냐세요 대만녀성 40대 이모애요 ~~\n루피를 좋아해서 코스프레 해봤어요 ~~~~\n어떤가요 ~~~','works_images/2루피.jpg',192,'2026-07-22 08:13:44.286269','2026-07-23 05:53:52.935668',36,'published',1),
(12,'진격의 거인','illustration','14살의 그림실력 (남자)','3D 애니메이션에 관심 많은 중학생입니다.\n진격거를 너무 재미있게 봤는데 제 재능이 있는지 대중의 판단이 필요해서\n많은 애니 덕후 선배님들 많이 계시는 이 곳에 올려보게 되었습니다.\n많은 관심 부탁드립니다.','works_images/1ㅈㄱㄱ.jpeg',1025,'2026-07-22 08:19:08.765158','2026-07-23 05:52:47.677561',37,'published',1),
(14,'원피스','novel','<안개섬의 여인>   조로 × 상디 × 미스터리한 여인 — 오리지널 사이드 스토리','1화. 안개 속의 검객\n그랜드라인 어딘가, 지도에도 제대로 표기되지 않은 작은 섬 하나가 있었다. 섬 전체가 회백색 안개로 뒤덮여 있어 뱃사람들 사이에서는 \"안개섬\"이라 불렸다. 물자 보급을 위해 잠시 정박한 밀짚모자 일당은, 각자 흩어져 마을을 둘러보기로 했다.\n\n조로는 늘 그렇듯 방향을 잃었다.\n\n\"…분명 항구 쪽으로 걸었는데.\"\n\n안개는 짙었고, 나무들은 하나같이 비슷하게 생겨 있었다. 몇 번째 갈림길인지도 모를 곳에서 조로는 걸음을 멈췄다. 발밑에서 부스럭거리는 소리가 들렸기 때문이다.\n\n수풀 사이로 누군가 쓰러져 있었다. 짙은 보라색 로브를 걸친 여인이었다. 얼굴 절반을 가리는 후드, 그 아래로 드러난 입술만이 핏기 없이 창백했다.\n\n\"어이, 괜찮아?\"\n\n조로가 다가가려는 순간, 여인의 손이 빠르게 움직여 그의 발목을 붙잡았다. 힘이 실린 손아귀였다. 쓰러져 있던 사람의 것이라고는 믿기지 않을 정도로.\n\n\"…쫓기고 있어요.\"\n\n여인이 낮게 속삭였다. 그리고 그 말이 끝나기도 전에, 안개 저편에서 발소리가 울려 퍼지기 시작했다. 여럿이었다.\n\n같은 시각, 마을 반대편 골목. 상디는 담배 연기를 길게 내뿜으며 낡은 식료품점 앞을 서성이고 있었다.\n\n\"이 섬, 뭔가 이상한데.\"\n\n지나가는 사람이 거의 없었다. 있다 해도 하나같이 고개를 숙인 채 종종걸음으로 사라졌다. 마치 누군가의 눈을 피하는 사람들처럼.\n\n그때 멀리서 조로 쪽 방향으로 짐승 우는 소리 같기도 하고 사람의 고함 같기도 한 소리가 울렸다. 상디의 눈썹이 꿈틀거렸다.\n\n\"저 멍청한 검사, 또 뭔 사고를 친 거야.\"\n\n그는 담배를 밟아 끄고 소리가 난 방향으로 몸을 돌렸다.\n\n2화. 추적자들\n조로는 여인을 등 뒤에 두고 칼자루에 손을 얹었다. 안개 사이로 그림자들이 하나둘 모습을 드러냈다. 검은 로브를 걸친 자들이었다. 얼굴은 보이지 않았지만, 걸음걸이에서 훈련받은 자들 특유의 절도가 느껴졌다.\n\n\"이 여자, 넘겨라.\"\n\n선두에 선 자가 낮게 말했다.\n\n조로는 대답 대신 칼을 뽑았다. 삼도류의 자세가 안개 속에서도 흔들림 없이 잡혔다.\n\n\"싫다면?\"\n\n말이 끝나자마자 그림자들이 일제히 달려들었다. 조로는 최소한의 움직임으로 첫 번째 상대의 무기를 튕겨내고, 두 번째 상대의 옆구리를 베었다. 하지만 숫자가 문제였다. 안개 속에서 몇 명이 더 튀어나올지 가늠이 되지 않았다.\n\n\"셋이서 붙는 건 좀 비겁하지 않아?\"\n\n익숙한 목소리와 함께, 다리 하나가 그림자의 얼굴을 걷어찼다. 상디였다.\n\n\"늦었잖아.\"\n\n\"길을 못 찾은 건 너였을 텐데.\"\n\n두 사람은 등을 맞대고 섰다. 손발이 맞지 않는 듯하면서도, 이상하리만치 서로의 빈틈을 메워가며 그림자들을 하나둘 쓰러뜨렸다.\n\n여인은 그 광경을 조용히 지켜보고 있었다. 후드 아래, 그녀의 눈동자가 미세하게 흔들렸다.\n\n마지막 그림자가 쓰러지자, 정적이 찾아왔다. 조로가 칼을 거두며 여인을 돌아봤다.\n\n\"이제 말해봐. 넌 누구고, 저것들은 뭐야.\"\n\n여인은 잠시 침묵하다가, 천천히 후드를 벗었다. 은빛에 가까운 백발, 그리고 왼쪽 눈가에 새겨진 낯선 문양 하나.\n\n\"제 이름은… 지금은 말씀드릴 수 없어요. 하지만 저들은 이 섬의 \'기억\'을 지키는 자들이에요. 그리고 저는, 그 기억에서 도망친 사람이고요.\"\n\n상디가 담배에 불을 붙이며 여인을 바라봤다.\n\n\"기억이라니. 무슨 말인지 하나도 모르겠는데.\"\n\n\"아가씨, 자세히 설명해 줄 수 있어?\"\n\n여인은 고개를 저었다.\n\n\"지금은 시간이 없어요. 저들 뒤에는… 더 큰 존재가 있어요. 곧 이 안개 자체가 움직일 거예요.\"\n\n그 말이 끝나기 무섭게, 발밑의 안개가 스스로 소용돌이치듯 일렁이기 시작했다.\n\n3화. 안개가 걷힐 때\n땅이 미세하게 진동했다. 안개는 이제 단순한 기상현상이 아니라, 의지를 가진 것처럼 세 사람 주위를 휘감아 돌았다.\n\n\"이거… 누가 조종하고 있는 건가?\"\n\n조로가 검을 고쳐 쥐며 중얼거렸다.\n\n여인이 품속에서 작은 나침반 모양의 유물을 꺼냈다. 바늘이 아닌, 희미하게 빛나는 문양이 표면에 떠올라 있었다.\n\n\"이 섬은 원래 지도에 없어요. 안개가 이 섬을 세상으로부터 숨겨온 거죠. 저는… 그 봉인의 일부였어요.\"\n\n\"봉인의 일부라니, 그게 무슨—\"\n\n상디의 말이 끝나기도 전에, 안개 중심에서 거대한 그림자가 서서히 형체를 갖추기 시작했다. 사람도 짐승도 아닌, 안개 그 자체로 이루어진 무언가였다.\n\n\"…저게 네가 말한 \'더 큰 존재\'야?\"\n\n여인이 고개를 끄덕였다.\n\n\"제가 봉인에서 벗어나면서, 안개의 균형이 깨졌어요. 원래대로라면 제가 다시 안으로 들어가야 해요. 그래야 이 섬도, 저기 있는 사람들도 안전해질 거예요.\"\n\n조로와 상디는 서로를 힐끗 쳐다봤다. 말하지 않아도 통하는 무언가가 있었다.\n\n\"그럼 방법은 하나네.\"\n\n상디가 담배 연기를 내뿜으며 앞으로 나섰다.\n\n\"저 안개 덩어리를 흩어놓으면 되는 거 아냐?\"\n\n\"단순하게 말하는군. 하지만—\" 조로가 씩 웃으며 검을 세 자루째 뽑아 들었다. \"나쁘지 않은 방법이야.\"\n\n두 사람은 동시에 안개의 그림자를 향해 달려들었다. 상디의 발차기가 안개의 몸통을 가르고, 조로의 검이 응축된 어둠을 베어냈다. 그림자는 비명 같은 소리를 내며 서서히 옅어지기 시작했다.\n\n그 틈을 놓치지 않고 여인이 유물을 높이 들어 올렸다.\n\n\"돌아가라. 나의 자리로.\"\n\n빛이 사방으로 퍼지며, 소용돌이치던 안개가 서서히 걷히기 시작했다. 마을 곳곳에 숨죽이고 있던 사람들이 하나둘 밖으로 나와 하늘을 올려다봤다. 몇 년 만에 처음 보는 맑은 하늘이었다.\n\n안개가 완전히 걷혔을 때, 여인의 모습도 함께 사라져 있었다. 남은 것은 그녀가 서 있던 자리에 놓인 작은 나침반뿐이었다.\n\n조로가 그것을 주워 들었다.\n\n\"…뭐였던 거야, 저 여자.\"\n\n상디는 대답 없이 담배 연기만 길게 내뿜었다. 안개가 사라진 하늘 위로, 두 개의 태양처럼 보이는 노을이 걸려 있었다.\n\n\"글쎄. 하지만 덕분에 이 섬 사람들은 오랜만에 하늘을 보네.\"\n\n두 사람은 나침반을 품에 넣고, 조용히 항구를 향해 걸음을 옮겼다. 동료들이 기다리고 있을 배를 향해서.\n\n— 完 —\n\n※ 이 이야기는 원작 스토리라인이나 특정 시점의 설정과 무관하게 진행되는 오리지널 사이드 에피소드입니다. 등장인물의 성격과 관계성은 원작을 기반으로 하되, 세계관 설정(지역명, 현상금, 최근 사건 등)과의 충돌을 피하기 위해 구체적인 시점은 의도적으로 특정하지 않았습니다.','works_images/KakaoTalk_20260723_143943998.png',433,'2026-07-23 05:27:44.662249','2026-07-23 05:50:53.663910',20,'published',1),
